window.CANON_INDEX = {"tracks":[{"id":"T1","name":"Control Hub & Platform Foundations","color":"#3ecfb2","rooms":[{"code":"T1-R01","title":"Control Hub Foundations","href":"rooms/T1-R01-control-hub-foundations.html","status":"written"},{"code":"T1-R02","title":"Identity & Directory Sync","href":"rooms/T1-R02-identity-directory-sync.html","status":"written"},{"code":"T1-R03","title":"Licensing & Subscriptions","href":"rooms/T1-R03-licensing-subscriptions.html","status":"written"},{"code":"T1-R04","title":"Locations & Sites","href":"rooms/T1-R04-locations-sites.html","status":"written"},{"code":"T1-R05","title":"Admin Roles & Partner Admin","href":"rooms/T1-R05-admin-roles-partner.html","status":"written"},{"code":"T1-R06","title":"Analytics & Troubleshooting Views","href":"rooms/T1-R06-analytics-troubleshooting.html","status":"written"},{"code":"T1-R07","title":"Data Residency & Security Basics","href":"rooms/T1-R07-data-residency-security.html","status":"written"}]},{"id":"T2","name":"Webex Calling","color":"#7eb6ff","rooms":[{"code":"T2-R01","title":"Calling Architecture Overview","href":"rooms/T2-R01-calling-architecture.html","status":"written"},{"code":"T2-R02","title":"Local Gateway & PSTN Options","href":"rooms/T2-R02-local-gateway-pstn.html","status":"written"},{"code":"T2-R03","title":"Dial Plans, PSTN & Routing","href":"rooms/T2-R03-dial-plans-pstn-routing.html","status":"written"},{"code":"T2-R04","title":"Devices & Provisioning","href":"rooms/T2-R04-devices-provisioning.html","status":"written"},{"code":"T2-R05","title":"Call Features","href":"rooms/T2-R05-call-features.html","status":"written"},{"code":"T2-R06","title":"Calling Security & Compliance","href":"rooms/T2-R06-calling-security-compliance.html","status":"written"},{"code":"T2-R07","title":"Survivability Gateway","href":"rooms/T2-R07-survivability-gateway.html","status":"written"},{"code":"T2-R08","title":"Calling Analytics & CDR","href":"rooms/T2-R08-calling-analytics-cdr.html","status":"written"}]},{"id":"T3","name":"Webex Contact Center (Multi-tenant)","color":"#f0b429","rooms":[{"code":"T3-R01","title":"WxCC Multi-tenant Overview","href":"rooms/T3-R01-wxcc-multitenant-overview.html","status":"written"},{"code":"T3-R02","title":"Tenant Provisioning & Setup","href":"rooms/T3-R02-tenant-provisioning-setup.html","status":"written"},{"code":"T3-R03","title":"Entry Points, Queues & Routing Strategies","href":"rooms/T3-R03-entry-points-queues-routing.html","status":"written"},{"code":"T3-R04","title":"Agent Desktop & Supervisor","href":"rooms/T3-R04-agent-desktop-supervisor.html","status":"written"},{"code":"T3-R05","title":"Voice Options","href":"rooms/T3-R05-voice-options.html","status":"written"},{"code":"T3-R06","title":"Digital Channels","href":"rooms/T3-R06-digital-channels.html","status":"written"},{"code":"T3-R07","title":"Analyzer & Reporting","href":"rooms/T3-R07-analyzer-reporting.html","status":"written"},{"code":"T3-R08","title":"Supervisor Experience","href":"rooms/T3-R08-supervisor-experience.html","status":"written"},{"code":"T3-R09","title":"WFO & AI Features","href":"rooms/T3-R09-wfo-ai-features.html","status":"written"}]},{"id":"T4","name":"Webex Contact Center Enterprise","color":"#ff8b9a","rooms":[{"code":"T4-R01","title":"WxCC Enterprise Overview","href":"rooms/T4-R01-wxcc-enterprise-overview.html","status":"written"},{"code":"T4-R02","title":"Core Components","href":"rooms/T4-R02-core-components.html","status":"written"},{"code":"T4-R03","title":"Call Flow Through WxCCE","href":"rooms/T4-R03-call-flow-wxcce.html","status":"written"},{"code":"T4-R04","title":"Scripting & ICM Routing","href":"rooms/T4-R04-scripting-icm-routing.html","status":"written"},{"code":"T4-R05","title":"CVP & VXML IVR","href":"rooms/T4-R05-cvp-vxml-ivr.html","status":"written"},{"code":"T4-R06","title":"Finesse Desktop & Gadgets","href":"rooms/T4-R06-finesse-desktop-gadgets.html","status":"written"},{"code":"T4-R07","title":"Reporting with CUIC","href":"rooms/T4-R07-reporting-cuic.html","status":"written"},{"code":"T4-R08","title":"Sizing & HA","href":"rooms/T4-R08-sizing-ha.html","status":"written"},{"code":"T4-R09","title":"Faisal Khan Classroom Index","href":"rooms/T4-R09-classroom-index.html","status":"written"},{"code":"T4-R10","title":"Hybrid & Cloud-connected Features","href":"rooms/T4-R10-hybrid-cloud-connected.html","status":"written"}]},{"id":"T5","name":"Dedicated Instance","color":"#c4b5fd","rooms":[{"code":"T5-R01","title":"What Dedicated Instance Is","href":"rooms/T5-R01-what-dedicated-instance-is.html","status":"written"},{"code":"T5-R02","title":"DI Architecture & Peering","href":"rooms/T5-R02-di-architecture-peering.html","status":"written"},{"code":"T5-R03","title":"Connectivity Options","href":"rooms/T5-R03-connectivity-options.html","status":"written"},{"code":"T5-R04","title":"DI Admin & Operations","href":"rooms/T5-R04-di-admin-operations.html","status":"written"},{"code":"T5-R05","title":"DI + Webex Calling Coexistence","href":"rooms/T5-R05-di-webex-calling-coexistence.html","status":"written"},{"code":"T5-R06","title":"DI Migration Path","href":"rooms/T5-R06-di-migration-path.html","status":"written"}]},{"id":"T6","name":"Migrations","color":"#c6e27a","rooms":[{"code":"T6-R01","title":"2,000-seat CUCM + UCCE Cutover","href":"rooms/T6-R01-enterprise-cutover-capstone.html","status":"written"},{"code":"T6-R02","title":"CUCM to Webex Calling","href":"rooms/T6-R02-cucm-to-webex-calling.html","status":"written"},{"code":"T6-R03","title":"Migration Tools","href":"rooms/T6-R03-migration-tools.html","status":"written"},{"code":"T6-R04","title":"UCCE/PCCE to WxCC","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html","status":"written"},{"code":"T6-R05","title":"Third-party PBX & CC to Webex","href":"rooms/T6-R05-third-party-pbx-cc.html","status":"written"},{"code":"T6-R06","title":"Number Porting & Cutover","href":"rooms/T6-R06-number-porting-cutover.html","status":"written"},{"code":"T6-R07","title":"Coexistence & Interop","href":"rooms/T6-R07-coexistence-interop.html","status":"written"},{"code":"T6-R08","title":"Post-migration Validation","href":"rooms/T6-R08-post-migration-validation.html","status":"written"}]},{"id":"T7","name":"SIP, Routing & Queues","color":"#ffb067","rooms":[{"code":"T7-R01","title":"SIP Fundamentals for Webex","href":"rooms/T7-R01-sip-fundamentals-webex.html","status":"written"},{"code":"T7-R02","title":"CUBE Deep Dive","href":"rooms/T7-R02-cube-deep-dive.html","status":"written"},{"code":"T7-R03","title":"Codecs, Media & NAT","href":"rooms/T7-R03-codecs-media-nat.html","status":"written"},{"code":"T7-R04","title":"SIP Trunk Design","href":"rooms/T7-R04-sip-trunk-design.html","status":"written"},{"code":"T7-R05","title":"Queue Theory for Contact Center","href":"rooms/T7-R05-queue-theory-contact-center.html","status":"written"},{"code":"T7-R06","title":"Routing Strategies Compared","href":"rooms/T7-R06-routing-strategies-compared.html","status":"written"},{"code":"T7-R07","title":"SIP Trace Reading Lab","href":"rooms/T7-R07-sip-trace-reading-lab.html","status":"written"}]},{"id":"T8","name":"Flows, Integrations, Troubleshooting & Latest","color":"#f0a0ff","rooms":[{"code":"T8-R01","title":"Flow Designer Essentials","href":"rooms/T8-R01-flow-designer-essentials.html","status":"written"},{"code":"T8-R02","title":"Flow Design Patterns","href":"rooms/T8-R02-flow-design-patterns.html","status":"written"},{"code":"T8-R03","title":"APIs, Webhooks & Webex Connect","href":"rooms/T8-R03-apis-webhooks-connect.html","status":"written"},{"code":"T8-R04","title":"CRM Integrations","href":"rooms/T8-R04-crm-integrations.html","status":"written"},{"code":"T8-R05","title":"AI in Webex Contact Center","href":"rooms/T8-R05-ai-wxcc.html","status":"written"},{"code":"T8-R06","title":"Troubleshooting Methodology","href":"rooms/T8-R06-troubleshooting-methodology.html","status":"written"},{"code":"T8-R07","title":"Logs & Tools","href":"rooms/T8-R07-logs-and-tools.html","status":"written"},{"code":"T8-R08","title":"Latest Features Radar","href":"rooms/T8-R08-latest-features-radar.html","status":"written"}]},{"id":"T9","name":"Workforce and Quality Management","color":"#34d399","rooms":[{"code":"T9-R01","title":"Workforce and quality, in plain words","href":"rooms/T9-R01-wfm-qm-foundations.html","status":"written"},{"code":"T9-R02","title":"Basic workforce management on Webex WFO","href":"rooms/T9-R02-basic-wfm.html","status":"written"},{"code":"T9-R03","title":"Basic quality management and recording","href":"rooms/T9-R03-basic-qm.html","status":"written"},{"code":"T9-R04","title":"AI Quality Management in Control Hub","href":"rooms/T9-R04-ai-quality-management.html","status":"written"},{"code":"T9-R05","title":"Quality reports in Analyzer","href":"rooms/T9-R05-qm-analyzer.html","status":"written"}]},{"id":"T10","name":"AI Agents and Voice AI","color":"#a78bfa","rooms":[{"code":"T10-R01","title":"Three AI names in Webex Contact Center","href":"rooms/T10-R01-three-ai-names.html","status":"written"},{"code":"T10-R02","title":"Voice path: Virtual Agent V2","href":"rooms/T10-R02-virtual-agent-v2.html","status":"written"},{"code":"T10-R03","title":"Language, voice, and custom events","href":"rooms/T10-R03-language-voice-events.html","status":"written"},{"code":"T10-R04","title":"Digital AI agents and the six channels","href":"rooms/T10-R04-digital-ai-channels.html","status":"written"},{"code":"T10-R05","title":"What the public AI pages will not support","href":"rooms/T10-R05-voice-ai-limits.html","status":"written"}]},{"id":"T11","name":"Bridges from CUCM and UCCE","color":"#38bdf8","rooms":[{"code":"T11-R01","title":"A bridge is not a cutover","href":"rooms/T11-R01-bridge-is-not-a-cutover.html","status":"written"},{"code":"T11-R02","title":"Local Gateway as the calling bridge","href":"rooms/T11-R02-local-gateway-bridge.html","status":"written"},{"code":"T11-R03","title":"Dedicated Instance and contact-center bridges","href":"rooms/T11-R03-di-contact-center.html","status":"written"},{"code":"T11-R04","title":"UCCX discovery into Webex Contact Center","href":"rooms/T11-R04-uccx-to-wxcc.html","status":"written"},{"code":"T11-R05","title":"Other platforms, without a fake bridge","href":"rooms/T11-R05-other-platforms.html","status":"written"}]}],"terms":[{"term":"Control Hub","def":"The central interface Cisco documents for the organization, users, services, and usage analytics. Calling location tasks sign in at https://admin.webex.com. [cite:5] [cite:4]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Webex identity","def":"The identity service the SSO guides configure. An IdP assertion has to land on a user Webex already knows. The SSO article’s contents name “Configure Webex Identity Service.” [cite:10]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"uid","def":"The SAML claim org SSO maps. You may map userPrincipalName, an email alias, or another attribute to uid, and the IdP must match one of the user’s email addresses to that uid at sign-in. [cite:10]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Partner SSO","def":"Service-provider SSO for customer orgs that partner manages. The IdP claim includes the mail attribute rather than uid. [cite:10]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Directory Connector","def":"The on-premises connector you download from Control Hub to provision Active Directory users into the org. It has a Windows and Active Directory requirements section. [cite:9]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"SCIM","def":"A REST API that keeps the user list in sync when someone is created, updated, or removed in the Entra application. No on-premises connector. [cite:11]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"SCIM tenant URL","def":"Commercial Webex uses https://webexapis.com/identity/scim/OrgId/v2. Webex for Government uses https://api-usgov.webex.com/identity/scim/OrgId/v2. [cite:11]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Entra ID Wizard","def":"The Control Hub wizard path that can synchronize groups, rooms, and avatars. SCIM 1.1 cannot. SCIM 2.0 can synchronize users and groups, and still not rooms or avatars. [cite:11]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"License","def":"What you administer to users from the Control Hub overview once a service is provisioned. SKU names for a given subscription stay in the licensing room. [cite:1]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Analytics window","def":"A standard customer can access 3 months of analytics data. A Pro Pack customer can access 13 months. [cite:12]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"SP-initiated SSO","def":"The ADFS guide says not to test SSO from the IdP interface. It says Webex only supports service-provider-initiated flows, and the Control Hub SSO test is the test. [cite:13]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Partner Hub","def":"The console named for administrators who manage multiple customer organizations. It is not the customer org’s Control Hub. [cite:2]","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"Troubleshooting view","def":"The Control Hub place where you search one Webex Calling call, see whether it succeeded, refused, or failed, and open media statistics. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Monitoring path","def":"The article’s click path is Monitoring → Troubleshooting. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"21-day window","def":"Troubleshooting shows calls for the past 21 days. Analytics can cross-launch into that same 21-day slice. [cite:1] [cite:2]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Call segment","def":"One piece of a call with its own outcome. A transfer can be several segments. The view is built so you can see which segment failed. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Correlation ID","def":"Groups related calls in the search view. Filters are not available when you searched by phone number or correlation ID. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Hop","def":"A leg of the media path. The article tells you to open hop details to see where quality broke. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"ICE","def":"Interactive Connectivity Establishment. One way media stays directly between the users instead of crossing the Webex Calling cloud. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"PNC","def":"Private Network Connect. One of the path-optimization values the article lists next to ICE and “No optimization.” [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Path optimization","def":"The call-details field. Accepted values in the article: ICE, PNC, or No optimization. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Partial search","def":"Phone number, user name, and device name can be partial. For a phone number, the first digits list candidates. Enter alone searches for an exact match. A pasted number needs the leading +1 for that search to work. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"CSV export","def":"Search results or troubleshooting call records, up to 100 records per file, for the tab you are on. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"JSON call report","def":"From the call details page, along with participant details as CSV. [cite:1]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Analytics","def":"Historical charts. Standard customers get 3 months. Pro Pack customers get 13 months. Not for billing. [cite:2]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Selectable range","def":"The article says that starting January 27, 2026 a Pro Pack admin can select at most 3 months at a time, while 13 months of history remain. That date is before this Canon pass. re-check the live picker. [cite:2]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Webex App calling history","def":"A separate sentence: Pro Pack has 13 months for calls based in Webex App, and everyone else has 3 months for those calls. Do not paste that sentence onto every Calling report without reading which dashboard you opened. [cite:2]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Calling media quality","def":"A Control Hub dashboard of KPIs and charts by location, IP, media type, connection, codec, endpoint, and phone model. [cite:2]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Worst-experience cross-launch","def":"Clicking a name in Users with worst calling experience opens Troubleshooting for that user’s media sessions in the selected dates, capped at 21 days. [cite:2]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Logs page","def":"Troubleshooting → Logs. Search the user by email and choose Collect logs. [cite:3]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"30-day client logs","def":"Uploaded Webex App logs are available for the last 30 days. The user can also send logs from the app. [cite:3]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Offline collection","def":"You cannot collect logs for a user who is offline. They need an active internet connection. [cite:3]","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#eco"},{"term":"Local Gateway","def":"The premises session border controller that terminates a Webex Calling trunk. Registration-based trunks are up to 250 concurrent calls and CUBE only. Certificate-based trunks are for more than 250 and a choice of device types. [cite:3]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"CUBE","def":"Cisco’s IOS XE session border controller. It is the only device for a registration trunk, and the getting-started article says it is the only SBC that currently supports Webex for Government. [cite:3] [cite:4]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Premises PSTN","def":"One of the three PSTN families for a location, alongside Cisco Calling Plan and Cloud Connected PSTN. The trunk is how premises PSTN reaches Webex Calling. [cite:1] [cite:7]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"RedSky","def":"The emergency provider in the enhanced emergency calling article. You get a RedSky account, set alert email addresses, and allow the phones and the Webex client to reach RedSky. [cite:14]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"HELD / HELD+","def":"HTTP Enabled Location Delivery. The article lists HELD+ as used by Webex App, with dynamic location via network discovery using a wiremap. Supported clients named there include Cisco MPP phones and Webex App. [cite:14]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Dispatchable location","def":"RAY BAUM’S Act Phase 2, begun January 2022, requires a correct dispatch address for non-fixed devices and nomadic users, including a Webex App user who leaves the premises. [cite:14]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Kari’s Law","def":"Public Law 115-127. A call from the organization to emergency services must generate an email notification. Control Hub can enable that for all locations or for selected locations. [cite:15] [cite:14]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"933","def":"A North American emergency test number for locations in the United States and Canada. It tests emergency-call email generation and does not alert public safety personnel. [cite:15]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"ECBN","def":"Emergency Callback Number. Extension-only users need an accurate ECBN: the location default, or another telephone number from that same location. [cite:17]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Call recording provider","def":"The provider you select for the organization before anyone enables recording for users. Article nhvl4hw says both of these: “Webex is the default value,” and, later, “Dubber is chosen by default, as there is no additional cost to include Dubber Go.” This Canon cites both sentences. It does not claim a screenshot of which control paints first. [cite:16]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Dubber Go","def":"Included with Webex Calling user entitlements at no additional cost. Unlimited recordings, each stored 30 days, and only the user manages them in the Dubber portal. [cite:16]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Survivability Gateway","def":"A different service from Local Gateway. BRKCOL-2312 describes it as a site gateway, managed from Control Hub, that routes internal, external, and emergency calls during an outage. [cite:5]","room":"T2-R02","href":"rooms/T2-R02-local-gateway-pstn.html#eco"},{"term":"Internal extension length","def":"Organization setting, 2–10 digits, default 4. Lengthening it does not rewrite existing speed dials to internal extensions. [cite:1]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Routing prefix","def":"Digits in front of an extension so two locations can reuse the same extension. Length 1–7, unique per location. [cite:1]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Steering digit","def":"The first digit of every routing prefix. It counts inside the prefix length. [cite:1]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Enterprise Significant Number","def":"Location routing prefix plus extension. Required for cross-location extension calls when inter-location extension dialing is off. [cite:1]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Outbound dial digit","def":"Optional digit users dial for an outside line. Default None. Use a different digit from the steering digit. E.164 calls ignore this prefix requirement. [cite:1]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Enterprise dial plan","def":"Global. Applies to all users. One routing choice: a trunk or a route group. Patterns are ESN/on-net, +E.164, or SIP URI domains. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Route group","def":"1 to 10 trunks. Same priority is random. An unavailable higher-priority trunk falls through to a lower priority. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Trunk","def":"Webex Calling to the premises, ending on a local gateway or another supported device. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Unknown extension","def":"2–10 digits, or inbound caller ID that matches no dial-plan pattern. Can be routed to a trunk or route group as a premises call. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Standard Behavior","def":"Recommended unknown-number handling once dial plans exist. Path: Services > PSTN & Routing > Services. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Legacy Behavior","def":"Kept for old local-gateway behavior. The article says not to use it once dial plans are configured. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Caller ID format","def":"+E.164 selects the external CLID. ESN selects the internal CLID. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Verify Call Routing","def":"Simulates a call from a cloud user, workspace, virtual line, or premises trunk. Shows permissions, fraud prevention, digit patterns, intercept, and translation. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Emergency Service Address","def":"Mandatory for U.S. and Canada Cisco Calling Plan locations. The same article later expands ESA as Enterprise Service Address in the validation paragraph. Quote the sentence you mean. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Cloud Connected PSTN","def":"Partner cloud PSTN. No local PSTN hardware for that choice. Still only for Webex Calling users. [cite:2]","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Cisco Calling Plan","def":"Cisco’s cloud PSTN. Needs a committed outbound calling plan and a supported country. Read the live country list in the location wizard. T2-R03 marks that list re-check.","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"TLS 1.2 and 1.3","def":"The SIP security article’s supported TLS versions for secure SIP. [cite:1]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"SRTP suite","def":"AES_CM_128_HMAC_SHA1_80 is the SRTP key the same article lists for secure media. [cite:1]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Calling E2EE","def":"Opportunistic. Disabled by default. Calls start on SRTP and upgrade when clients support it and nothing forces media processing. [cite:2]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"end-end encryption toggle","def":"The article’s hyphenation. Services > Calling > Settings > Webex App tab > Security. [cite:2]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Recording defeats E2EE","def":"Call recording makes the service process media, so E2EE is disabled. [cite:2]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Webex recording provider","def":"nhvl4hw says both “Webex is the default value” and “Dubber is chosen by default.” Quote both. Retention one year and 100 GB. [cite:3]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Dubber Go","def":"30 days, with a user portal, in the same recording article. [cite:3]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"RedSky","def":"Emergency provider for Webex Calling and for WxCC WebRTC desktops. Hosts api.wxc.e911cloud.com and wxc.e911cloud.com, port 443. b2exve does not name TCP on that row. [cite:4] [cite:5]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"933","def":"nvfbjts says place 933 calls, then activate Emergency call routing. nj0abhbb’s “without alerting public safety personnel” sentence is the Calling email test for the United States and Canada. Read nvfbjts before you say the WxCC test reaches a PSAP. The article does not say.","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Device User Id","def":"For a contact-center agent in RedSky, the identification type must be Device User Id and it must equal the agent email. Then install myE911. [cite:5]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Kari and RAY BAUM","def":"nvfbjts: direct 911, internal notification, and a dispatchable location for WebRTC desktops that have no traditional phone. [cite:5]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"mTLS FQDN","def":"The certificate CN or SAN must match the Control Hub FQDN. The article’s example strips :5061 off london.lgw.cisco.com. [cite:1]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Server Authentication EKU","def":"Supported alone. Webex does not require Client Authentication EKU. Some third-party SBCs reject that certificate. [cite:1]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Edge SRV port 5061","def":"The nslookup example in jwkbt2 advertises 5061 for endpoint discovery. Trunk destinations in the port reference are 5062 and 8934. Do not merge them. [cite:1] [cite:4]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Zero-trust meetings","def":"MLS, up to 1000 participants. PSTN and SIP devices are not in those meetings. In-meeting AI Assistant, NBR, and transcription need decrypted media and are not in ZT meetings. Not the same switch as Calling E2EE. [cite:2]","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Government cloud","def":"A different port and crypto page. This room does not paste it into the commercial ACL.","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#eco"},{"term":"Entry point","def":"Where a contact enters. The architecture article pairs it with a flow. [cite:1]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Flow","def":"The routing logic a contact runs before a queue. Virtual Agent activities live in the flow. [cite:1] [cite:15]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Queue","def":"The wait point that offers work to a team. Routing patterns are configured under Contact Center → Customer experience → Queues. [cite:8] [cite:6]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Analyzer","def":"Reporting built from contact-center events, as the architecture article describes it. Session behavior is tajemk, retrieved 2026-10-14, not this architecture sentence. [cite:28] [cite:1]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Search API","def":"Historical search. FROM cannot be older than 36 months from the current time. The duration between TO and FROM must not be more than 365 days. Scopes cjp:config or cjp:config_read. Roles: Administrator or Supervisor. [cite:9]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"CRM connector","def":"Cisco’s integration that launches the agent Desktop inside Salesforce, Dynamics 365, or ServiceNow. Digital channels such as chat and email are not supported on these connectors. [cite:12]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"CIF","def":"Microsoft’s Channel Integration Framework, as Cisco’s Dynamics article uses it. Single-session Dynamics apps require CIF version 1. Multi-session apps require CIF version 2. On-premises Dynamics is not supported. [cite:13]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Virtual Agent–Voice","def":"Self-service that integrates the IVR with cloud AI through a Contact Center AI connector. Supported integrations named in the article: Google Dialogflow CX, Dialogflow ES, and bring-your-own virtual agent. [cite:15]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"AGENT_TRANSFER","def":"A mandatory bring-your-own virtual agent event. The call must be escalated to a queue of human agents with that event. [cite:19]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"AI Assistant","def":"A Control Hub add-on for Webex Contact Center. The enablement article includes AI-generated summaries (call drop and agent transfer), automated wellness breaks, Auto CSAT, real-time transcription, and Real-Time Assist. [cite:16]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"WFO Agent Assist","def":"Described on the agent what’s-new page as a GenAI assistant in Webex WFO for schedules, time off, and overtime, with responses in 59 languages checked against WFM rules. [cite:17]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Connect","def":"The digital-channel path the architecture article names. Chat and email on that path are not the same thing as the CRM connectors, which exclude those channels. [cite:1] [cite:12]","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#eco"},{"term":"Entry point","def":"The ingress for a contact. Telephony maps it to the phone number the call arrives on. Email and messaging entry points point at the Webex Connect configuration. [cite:1]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Routing strategy","def":"A schedule on an entry point or queue: start and end date, start and end time in 0000–2400, selected weekdays, and a routing flow with a live or latest version. [cite:4]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Default routing strategy","def":"The flag that makes one strategy the default for that entry point or queue during the time window you set. The article prints the toggle twice in the same procedure. [cite:4]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Business Hours","def":"The model the routing-strategy article tells you to move toward. It does not delete existing strategies. This room does not restate the holiday-priority arithmetic from a different article.","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Queue","def":"The holding place for telephony, chat, email, or social contacts until an agent is selected or the contact is picked up. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Call distribution group","def":"A level of teams on a team-assignment queue. If nobody matches, the contact parks for the configured interval, then the next group is added to the search. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Check Agent Availability","def":"A Queue Contact toggle. If the current call distribution group has no matching agent, the contact expands to the next group immediately instead of waiting out the interval. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Longest Available","def":"Among eligible agents, choose the one who has been available the longest. It is the default routing pattern for a non-skill queue with team assignment. [cite:3]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Circular","def":"Round-robin through the configured agent order. The next contact starts after the agent who took the last one. It is the default for a non-skill queue with agent assignment. [cite:2] [cite:3]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Top-down","def":"Also called Linear. Always walk the ordered agent list from the beginning and take the first available agent with a free channel for that media type. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Best Available","def":"Among agents who fully meet the skill requirements, pick the highest proficiency score. Weights apply to proficiency skills for this pattern. They do not change Longest Available. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Skill criteria on the queue","def":"Skills configured on the queue itself. Any agent whose direct skill profile fully satisfies them is implicitly on the queue. Team does not associate the agent. The contact cannot override the criteria. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Skill requirements in the flow","def":"A team-assignment queue where the flow injects the skills for this contact, and can relax them on a timer while call distribution groups expand. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Skill score","def":"Best Available scoring uses proficiency values of the skills named in the requirement. A less-than-or-equal condition inverts that skill as 10 minus the value. Boolean, text, and enum skills are eligibility filters, not score inputs. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Agent assignment","def":"Agents are added directly to the queue, up to 1000, in an order the routing pattern can use. There is no time-based target expansion. If nobody is free, the contact parks until one of those agents is free or the park times out. [cite:2] [cite:3]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Team login","def":"An agent on two teams is considered only in the team they sign in to, and therefore only in the call distribution group that contains that team. [cite:2]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"QueueToAgent","def":"Voice-only path in the architecture article: send the contact to an agent id, and park it on an agent-specific queue if that agent is busy. [cite:1]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Variable queue","def":"Queue Contact can take a queue id from a flow variable, with a fallback queue if the variable is not a valid id. If you also needed skill requirements, the article says the contact is routed Longest Available and the queue’s selected algorithm is overridden. [cite:5]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Get Queue Info","def":"Returns position in queue and estimated wait. Success needs both positive. Team assignment with skills in the flow always returns estimated wait of −1. That product rule is not the Erlang study model on the Labs page. [cite:5]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Webex Connect","def":"Where a non-telephony flow is chosen for messaging and social. The architecture article separates that from the telephony entry point’s routing strategy. [cite:1]","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#eco"},{"term":"Agent Desktop","def":"The browser desktop. Display greater than 500×500. Zoom 100%. One browser and one tab. [cite:1]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"WebRTC Desktop","def":"Handle calls using Desktop. The browser is the phone. Headset control actions are not supported. [cite:1]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Dial Number","def":"A Webex Calling number on the profile. International format uses the country-code checkbox. Other formats are E.164 or IDD. [cite:1]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Extension","def":"A Webex Calling extension. One configured extension is prefilled. Several become a dropdown of pre-validated extensions. [cite:1]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Auto sign-in","def":"Don’t show this again. Preferences are stored in the browser. A bad saved dial number sends you back to the preferences screen. [cite:1]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"RONA","def":"Redirect on no answer. The sign-in article ties it to missing browser permission and to an invalid dial number or extension, and to E911 accepted with telephony still down. [cite:1]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Team","def":"Agents associated with one site. Parent site cannot be edited later. Active by default. Delete only when inactive. [cite:2]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Agent-based team","def":"A listed set of agents. Optional desktop layout and multimedia profile. [cite:2]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Capacity-based team","def":"Dial number and capacity. No named agent list and no multimedia profile. [cite:2]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Skill profile","def":"Optional when skills-based routing is enabled. At most 500 agents share one. Team assignment copies the team’s profile onto the agent. Changes apply without a new sign-in. [cite:2]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Queue ranking","def":"Optional per team, per media type. At most 50 queues across all media types. Unranked queues show None. [cite:2]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Desktop layout","def":"Optional on an agent-based team. Users see new layout-based features after they sign in or reload. Team edits and layout edits show up together in the audit log. [cite:2]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Interactions page","def":"Supervisor workspace: Active, Queued, and Completed. Listen and barge are here. [cite:3]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Listen","def":"Monitor one agent from the interaction details. Answer the monitoring call. Pause mutes the supervisor’s audio. [cite:3]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Barge In","def":"Join as a participant after listen. Not available during consult. [cite:3]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Granular agent state","def":"Control Hub toggle available April 30, 2026 through October 29, 2026, then general availability. Leave it off to keep using Webex WFO. [cite:3]","room":"T3-R04","href":"rooms/T3-R04-agent-desktop-supervisor.html#eco"},{"term":"Analyzer","def":"The Webex Contact Center reporting application. It mines real-time and historical data and shows visualizations, dashboards, and folders on one home page. [cite:1]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Visualization","def":"The report object you run. Stock reports live under Visualizations and are read-only. [cite:1]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Real-time report","def":"Stays available indefinitely because the data refreshes automatically. A new real-time report defaults to a 5-second refresh. The Refresh drop-down runs from 5 to 60 seconds in steps of 5. [cite:1]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Historical report","def":"Stays active for 8 hours. After that you may need to re-authenticate for the latest updates. Visible data does not expire if you do not scroll or reload. [cite:1]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Real-time alert","def":"The Threshold Alerts window. Auto-refresh is every 3 minutes unless you stop it. [cite:1]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Agent statistics widget","def":"The desktop widget. Its historical report updates every 24 hours. Its real-time report updates every 60 seconds. That is not the Analyzer visualization refresh. [cite:2]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Stock report path","def":"Example: Stock Reports > Historical Reports > Agent Reports. Agent Statistics is a table on that path. [cite:3]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Sudden Disconnected Count","def":"A field the stock-report article says is not used and will not be populated. Do not coach agents from a zero in that column. [cite:3]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Export","def":"Historical visualizations can export Excel or CSV. Real-time and compound visualizations cannot. A drill-down with real-time data cannot. [cite:1]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Auto CSAT report","def":"An AI Assistant report. One row per agent, with average, minimum, and maximum predicted scores, also sliced by team and queue in the article’s questions. [cite:4]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Topic Analytics","def":"Trending Topics and Topic Summary reports for contact drivers. [cite:4]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Agent Wellness Breaks","def":"The Analyzer report for wellness breaks given to agents. [cite:4]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"KPI latency","def":"Supervisor Desktop KPI cards are push-based. Analyzer is pull-based: the UI requests data. [cite:5]","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Search API","def":"A different historical door. 36-month and 365-day windows are in T3-R01. Do not call that window an Analyzer refresh rate.","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"CUIC","def":"The Enterprise reporter. Post-upgrade cleanup in a WxCC 1.0 move exposes legacy Analyzer data. It does not convert CUIC. The CUIC row stays marked in T6-R04.","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Duration field","def":"tajemk says a visualization has Duration and Interval, and that a long duration with a short interval cannot run. The enumerated duration labels are not copied into this glossary.","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#eco"},{"term":"Webex CCE","def":"The article’s short name for Webex Contact Center Enterprise, a cloud contact center for large enterprises. [cite:1]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"WxCC","def":"Multi-tenant Webex Contact Center. A different row in the same deployment-model list. [cite:1]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"UCCE","def":"Unified Contact Center Enterprise. The article points at component documentation rather than folding it into Webex CCE. [cite:1]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"PCCE","def":"Packaged Contact Center Enterprise. Listed as its own deployment model. [cite:1]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Quick Deployment Solution","def":"A packaged Enterprise offer: 500 to 24,000 concurrent agents, U.S. only at the start, a fixed day-1 feature set. [cite:2]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Standard agent","def":"Day-1 license on that offer: inbound and outbound voice, browser-based desktop, web and voice callbacks. [cite:2]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Premium agent","def":"Adds email and web chat, multi-channel reporting and analytics, and supervisor monitoring and barge-in. DTMF IVR, Virtual Assistant–Voice via Google Dialogflow, and nailed-up mobile agent are day-1 items on the same offer, not inside the Premium-only sentence. [cite:2]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"A2Q","def":"Assurance to Quality review. Customizations are evaluated there and add time. They are not in the initial quick deployment. [cite:2]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Edge Connect 3.0","def":"In the Dedicated Instance customer example, one peer can serve both Dedicated Instance and Webex Contact Center Enterprise. [cite:3]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"WFO SKU scope","def":"Article py6u9h states its feature SKUs for Webex Contact Center Enterprise, Contact Center Enterprise, and Contact Center Express. [cite:7]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Flow Designer","def":"The build-and-manage article is for Webex Contact Center flows. This room does not assign that tool to Enterprise scripting. [cite:8]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Data sheet","def":"The pointer in the Dedicated Instance article for Enterprise details. Numbers on that sheet were not copied here. [cite:1]","room":"T4-R01","href":"rooms/T4-R01-wxcc-enterprise-overview.html#eco"},{"term":"Dedicated Instance","def":"An optional add-on to Webex Calling. You purchase it before activation. It is a private-cloud UC stack for a region, not the multi-tenant calling service. [cite:1]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Region activation","def":"Once a region is activated it cannot be reversed or moved. The voice service domain from the first region applies to later regions in the same Control Hub org. The UC applications domain cannot be changed after submit or activate. [cite:1]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"EMEA freeze","def":"The activation article says there are no new Dedicated Instance deployments in the EMEA region. Choose EU or UK. [cite:1]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Unified CM","def":"Deployed and sized at activation from the professional, standard, and workspace counts you enter for that region. [cite:1]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Unity Connection","def":"Deployed with the region. Listed again on the application-access article. [cite:1] [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Expressway","def":"Expressway Core and Edge are part of the activation set and of the application list. Expressway Edge is the node the access article ties to a public IP. [cite:1] [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Emergency Responder","def":"Deployed only in the AMER region. [cite:1] [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"IM and Presence","def":"Named in the application-access article as part of the architecture. The activation article’s numbered deploy list that this pass read is Unified CM, Unity Connection, Expressway, and Emergency Responder in AMER. Do not treat those two lists as the same sentence. [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"SME","def":"Session Management Edition is optional. The cluster can span regions. It is listed under the publisher’s region on Manage. [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"UC application pane","def":"Calling → Dedicated Instance → Manage → UC application. It shows datacenter, voice service domain, and the Expressway Edge public IP. [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Over-the-top launch","def":"You can cross-launch the UC apps from Control Hub before peering is finished, so onboarding of the apps can start. [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Service list","def":"The access article lists Provisioning (publisher only), Call Processing, CTI Manager, Music on Hold, and TFTP. Application changes sync on a 24-hour schedule. [cite:2]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Edge Connect","def":"Private peering through Equinix or Megaport from the customer edge to the Webex backbone. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Webex BGP ASN","def":"The Edge Connect article states the Webex public BGP ASN is 13445. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Peering subnet","def":"Customer BGP peering link address space is a public IP with a /30 or /31 prefix. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Two DI links","def":"The migration-practice article says two Dedicated Instance links are a must. Four links are an option in pairs, and crossing is not allowed. Do not prefer one link for DI traffic. Each data center advertises its own /25. [cite:4]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Redundancy checkbox","def":"For an Edge Connect for Dedicated Instance order, the redundancy option is mandatory so the second connection lands in a different Webex data center in the region. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Data-center pair","def":"Primary and secondary Dedicated Instance data centers are grouped as a pair in each region. Either site in the pair can be primary. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Private ASN prepend","def":"AS-PATH prepending is not supported with private ASNs, because Webex strips the ASN after ingress. The article points at link-priority communities instead. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Link-priority community","def":"Edge Connect honors 13445:200, 13445:300, and 13445:400 as local preference 200, 300, and 400. [cite:3]","room":"T5-R02","href":"rooms/T5-R02-di-architecture-peering.html#eco"},{"term":"Scenario size","def":"2,000 seats is the design exercise in this room. It is not a Cisco limit and it is not a concurrent-call count.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Canon planning","def":"The phase list and the cutover runbook below are a Canon method. Cisco has not published a 2,000-seat CUCM plus UCCE runbook in the articles this room cites.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"PPDIO","def":"The calling migration introduction is the door for Unified CM to Webex Calling. The contact-center cutover is not that article. [cite:1]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Concurrent calls","def":"t9xctu Table 5, as of 2026-10-14: up to 250 concurrent prefers registration OTT; about 250–2000 prefers certificate OTT; about 2000–6500 prefers certificate interconnect. Size trunks from concurrent calls. [cite:2]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Premises PSTN limit","def":"Calls that originate from premises users cannot use cloud PSTN. [cite:3]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"CSS versus patterns","def":"CUCM closest-match is not the Webex wildcard engine. Field equivalence stays marked in T6-R02 and T2-R03.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"No ICM import","def":"None of the three published tools imports an ICM script into Flow Designer. Those rows stay marked in T6-R04. [cite:4]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"CCX jar is not UCCE","def":"0hd75db is Unified CCX. Do not point it at a UCCE logger. [cite:4]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Entry point","def":"The multi-tenant front door: entry point, flow, queue, team. [cite:5]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Pilot","def":"The 1.0 article says test a few users before you move everyone. That article is inside WxCC 1.0, not UCCE. The Canon method copies the caution, not the product. [cite:6]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"933 before agents","def":"WebRTC agents need RedSky tested before they take live calls. [cite:7]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Recording choice","def":"Quote both nhvl4hw defaults. Recording also disables Calling E2EE. [cite:8] [cite:9]","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Analyzer versus CUIC","def":"Keep CUIC until someone compares a report by hand. Cleanup of WxCC 1.0 does not convert CUIC.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Dual desktop","def":"Finesse and Agent Desktop on the same UCCE call stays marked in T6-R04. This runbook does not schedule that coexistence.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Number move","def":"Move one number only after the new flow answers. Do not move numbers with the CCX workbook.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Rollback","def":"Leave the old route in place until the new path has answered a test call. Canon planning, not a Cisco command.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"PPDIO","def":"Prepare, Plan, Design, Implement, Optimize. The migration introduction’s process. [cite:1]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Flash-cut","def":"Move all users and devices at once. Fastest, and the introduction contrasts it with a phased approach. [cite:1]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Phased migration","def":"Groups move over time. Users are split across Unified CM and Webex Calling until phase 2. [cite:3]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Local Gateway","def":"For a phased move the introduction names ISR 1100 and 4000, Catalyst 8200 and 8300, Catalyst 8000V, and certified third-party SBCs. [cite:1]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Unmatched call","def":"A destination Webex Calling does not own. The configuration workflow sends those calls, including unseen Unified CM extensions, to the Local Gateway. [cite:8]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"+E.164","def":"The form the configuration workflow attributes to Unified CM normalization. [cite:8]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Main number","def":"Set for each location. It can belong to a user or to a feature such as an auto attendant. [cite:4]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Migration Insights","def":"Control Hub path Services → Upgrades & Migrations → Migration Insights. Unified CM data can be uploaded as a .tar. [cite:5]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Migrate features from UCM","def":"Control Hub card under Services → Updates & Migrations. Maps auto attendant, devices, lines, layout, virtual line, call queue, hunt group, call park, and user calling data. [cite:6]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"UserBasedUCMFeatureMigration","def":"Python script that processes Unified CM CDR for migration tasks. This room does not describe its internals. [cite:6]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Enterprise to MPP","def":"7800 and 8800 phones can be moved with Control Hub’s “Migrate your phone to Webex Calling” tool. 8821 and 8831 are not eligible for MPP. [cite:4] [cite:7]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"BroadWorks migration","def":"A different Control Hub tool. PBX type BroadWorks or BroadCloud. The do_not_move_phone flag is BroadWorks-only. [cite:9]","room":"T6-R02","href":"rooms/T6-R02-cucm-to-webex-calling.html#eco"},{"term":"Unified CCX","def":"Cisco Unified Contact Center Express. Article 0hd75db migrates it to Webex Contact Center with a discovery jar and a bulk workbook. [cite:1]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Discovery tool","def":"The CCX extract. The page says download v3.5 and the command names uccx-to-webexcc-v3.4.jar. It needs Java 8 or above, CCX server access, and the CCX administrator account. Default port 443 if you omit the port. [cite:1]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"WebexCC_Bulk_Upload","def":"The workbook and prompts zip the discovery tool writes. Edit the sheets, then import through Control Hub Bulk Operations. A CSV over 5000 rows must be split. [cite:1]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"WxCC 1.0","def":"The legacy Webex Contact Center platform in article nb2ve0e. The upgrade enrolls the tenant, copies Management Portal configuration, and then you create flow scripts. [cite:2]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Pre-Upgrade Setup","def":"Contact Center > Settings. Carries tenant settings, provisions the new Management Portal, copies configuration, provisions voice and digital channels, and creates agent accounts. Do not change the legacy Management Portal while it runs. [cite:2]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Post-Upgrade Cleanup","def":"Same Settings area, after you are finished with the legacy platform. It decommissions the legacy Management Portal, and it makes legacy recordings and Analyzer data available on the new platform. [cite:2]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Tenant Data Migration Tool","def":"Webex CCE portal-to-portal copy. Use cases include a POD move, an upgrade of UCCE for a tenant, and sandbox to production. It copies portal classes, not ICM scripts into Flow Designer. [cite:3]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Routing controls","def":"A CCE portal class. Flag 1 on the tenant tool replaces every routing control on the target. [cite:3]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Peripheral gateway","def":"On Webex CCE, Bulk Request can migrate agents from one peripheral to another and identify their skill groups. Multi-tenant architecture does not name a PG. [cite:4] [cite:5]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Common Identity phase 1","def":"Webex CCE Portal provisioning so agents and supervisors sign in to Finesse with Webex Common Identity. [cite:4]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Entry point","def":"Multi-tenant ingress. Telephony maps it to a number. A flow is attached through a routing strategy. [cite:5]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Flow Designer","def":"Where you build the multi-tenant voice flow. The 1.0 article calls the new scripting surface Flow Control and says legacy routing strategies are incompatible, so you create them again. [cite:2] [cite:5]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Team","def":"Multi-tenant group of agents at a site. The CCX workbook has a Team sheet with type AGENT or CAPACITY. That sheet is a CCX extract, not a UCCE skill group. [cite:1]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Analyzer","def":"Multi-tenant reporting fed by contact events. After 1.0 cleanup, legacy Analyzer data is reachable from the new Analyzer. CUIC is unmarked. [cite:2] [cite:5]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Agent Desktop","def":"The multi-tenant desktop. nb2ve0e says agents cannot simultaneously access both the legacy and new desktops. A separate “at the same time” sentence is about Recording Management. [cite:2]","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Canon method","def":"This room’s study sequence for UCCE or PCCE into multi-tenant WxCC: build beside the old estate, test a few agents, cut one number after the flow answers, keep CUIC until Analyzer is compared by hand. It is Canon planning.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Local Gateway","def":"The customer SBC that trunks to Webex Calling. SIP TLS secures the signaling. SRTP secures the media. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Registration trunk","def":"Digest authentication, CUBE only, up to 250 concurrent calls. The sample dial-peer sets max-conn 250 and the article says that is the maximum for a registration trunk. [cite:1] [cite:2]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Certificate trunk","def":"Certificate authentication and FQDN checks. Concurrent calls above 250. Every SIP transaction the gateway starts, including OPTIONS, needs a Contact header with the gateway FQDN or Control Hub will not show the gateway online. [cite:2]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Webex for Government","def":"Certificate-based only, and CUBE is the only SBC the get-started article names for it. The commercial SHA1_80 step is marked not applicable. GCM is mandatory. [cite:1] [cite:2]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"voice class tenant","def":"Groups the trunk’s registrar or sip-server, transport, and SRTP crypto so the dial-peer can inherit them. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"SRTP SHA1_80","def":"Commercial Webex Calling: the article’s crypto class offers AES_CM_128_HMAC_SHA1_80 and says Webex Calling only supports SHA1_80. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"SRTP GCM","def":"Webex for Government: AEAD_AES_256_GCM is mandatory. Do not paste the commercial cipher onto a Government gateway. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"incoming uri request","def":"Matches the inbound INVITE to the Webex dial-peer. The article’s uri class looks for the trunk’s dtg= value from Control Hub. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"BAD.BAD","def":"A dummy destination-pattern on the Webex dial-peer. The article says a dummy is required when outbound calls are routed with an inbound dial-peer group. It is not a number your users dial. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"session target sip-server","def":"Sends the outbound leg to the SIP server inherited from the tenant. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"OPTIONS keepalive","def":"A voice class sip-options-keepalive profile. Certificate trunks depend on OPTIONS for the Control Hub online state. The article’s sample uses transport tcp tls. [cite:1] [cite:2]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Inbound SIP order","def":"IOS XE checks URI via, then URI request, then URI to, then URI from, then called number, then calling number, then destination-pattern against the ANI. The first criterion that matches wins. It is not digit-by-digit. [cite:3]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"dial-peer hunt 0","def":"The default hunt: longest match, then explicit preference, then random. Preference 0 is better than preference 1. [cite:3]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"huntstop","def":"Stops the gateway from trying the next outbound dial-peer after a failure. [cite:3]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"show dial-peer voice summary","def":"The IOS routing article prints this command. The summary line includes the hunt scheme. [cite:3]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"debug voip ccapi inout","def":"The same article prints this debug when a call fails on the first dial-peer and hunts. It is not the Local Gateway article’s first troubleshooting step. [cite:3] [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Diagnostic signature","def":"The Local Gateway article’s troubleshooting method. TAC-authored, signed XML. A high-CPU signature disables debugs. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"DS 64224","def":"The article tells you to install this high-CPU signature so that at 75 percent CPU it disables all debugs and uninstalls diagnostic signatures. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Config Validation","def":"A Control Hub check for registration-based Local Gateways only. It validates the Webex-facing dial-peers, tenant, and trustpoint. It does not validate the PSTN dial plan. [cite:4]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"ICE-Lite","def":"stun usage ice lite on Webex-facing dial-peers so media can optimize. The article says recording and other cloud media services cannot be optimized. [cite:1]","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#eco"},{"term":"Flow Designer","def":"The drag-and-drop surface that routes real-time calls and decides what happens at each stage, including how agents are assigned. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Start Flow","def":"Default activity on the main canvas. Cannot be deleted. Names the triggering event. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Event flow","def":"Optional, asynchronous, not predictable from the main path. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Get Queue Info","def":"Returns the caller’s position in queue (PIQ) and estimated wait time (EWT), plus other output variables. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"EWT −1","def":"The value Get Queue Info always returns for queues with team assignment and skills assigned in the flow. EWT does not apply there. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Insufficient Information","def":"The branch when PIQ is valid and EWT is −1. You can use PIQ. EWT was not calculated. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Success branch","def":"Both EWT and PIQ come back positive. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Queue priority","def":"An integer variable from 1 through 9. Outside that range, the default priority is 10. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Fallback queue","def":"Used only when a queue variable fails to return a valid queue ID. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"NewPhoneContact.DNIS","def":"The DNIS presented to the receiving entry-point flow after a transfer. Format depends on how that entry point is numbered. [cite:1]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"BRE Request","def":"A Flow Designer utility activity. The Business Rules Engine guide says you can build a flow that invokes it. [cite:2]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"QueueToAgent","def":"Named in the multi-tenant architecture article as voice, direct to an agent id. It is a different sentence from this room’s Queue Contact activity. [cite:3]","room":"T8-R01","href":"rooms/T8-R01-flow-designer-essentials.html#eco"},{"term":"Webex Connect","def":"Programmable CPaaS. APIs, SDKs, and low-code tools for the six areas on the product page. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Channel asset","def":"Email configuration, app, messaging account, phone number, sender, or channel-specific application. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Service","def":"Workspace for the assets, integrations, credentials, flows, and rules of one use case. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Flow Builder","def":"Connect’s designer for multi-step flows: design, test, publish, manage. Not Flow Designer and not an ICM script. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Rules","def":"Trigger, condition, and action for shorter automation than a flow. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Inbound webhook","def":"External application notifies Connect and can start a flow or a rule. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Outbound webhook","def":"Connect delivers receipts and incoming messages to an application. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Custom node","def":"Reusable REST or SOAP call inside a flow. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Service key and JWT","def":"The two authorization styles the integration table names. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"AI Agent Studio","def":"Where Connect says you create and manage AI agents. Fulfillment flows connect agent actions back to Connect flows. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Contact policy","def":"Consent, preferences, and how often you may contact someone. [cite:1]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Task","def":"A request for agent work. A telephony task is an incoming call. A chat task is a session. An email task is a chain. [cite:2]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"cjp:config","def":"One of the two scopes the Tasks Call Control page requires. The other is cjp:config_read. [cite:2]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"telephony_calls","def":"The Calling webhook resource that carries the recording lifecycle events. Scope spark-admin:calls_read. [cite:3]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"convergedRecordings","def":"List Events resource for “a Webex call was recorded for a user.” serviceType is mandatory when that resource is set. [cite:3]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"CRM connector","def":"Cisco’s Salesforce, Dynamics 365, or ServiceNow screen pop. Chat and email are not supported on those connectors. Connect is the digital path. [cite:4]","room":"T8-R03","href":"rooms/T8-R03-apis-webhooks-connect.html#eco"},{"term":"Cisco AI Assistant","def":"A paid add-on for Webex Contact Center, generally available as of the article header October 06, 2026. Agent Desktop shows an icon. The administrator can turn features off. [cite:1]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Dropped call summary","def":"An AI-generated summary when a call disconnects, so the next agent can continue. [cite:1]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Virtual agent transfer summary","def":"A summary of the virtual-agent portion when the contact reaches a human. [cite:1]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Mid-call summary","def":"On consult or transfer. As of that article, only direct agent-to-agent consults and transfers. Queues, entry points, dial numbers, and organization contacts are not supported yet. [cite:1]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Auto CSAT","def":"Predicts a satisfaction score from operational data, transcripts, and surveys. Supervisors see it in Analyzer and on Interaction Details. [cite:1]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Real-Time Assist","def":"Live recommendations on voice and digital. [cite:1]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Scripted AI agent","def":"Predefined rules and a training corpus. Selected in Flow Designer as Webex AI Agent Scripted. [cite:2] [cite:3]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Autonomous AI agent","def":"Goals and a knowledge base, with less human intervention. Voice access is currently limited to specific customers. [cite:2] [cite:3]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"AI Agent Studio","def":"Where agents are created. Voice preview works when Studio is opened from Control Hub > Services > Contact Center. [cite:3]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Virtual Agent V2","def":"The Flow Designer activity. Outcomes: Handled, Escalated, Errored. [cite:2]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Knowledge source","def":"Files, articles, or websites for autonomous agents. Do not upload PCI, PII, PHI, or other sensitive data. [cite:3]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Connect AI Agent node","def":"Digital flows on Webex Connect. Process Message and Close session. Timeout is 15 seconds. [cite:2]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Six digital channels","def":"As of s0qro1, header August 25, 2026: WhatsApp, SMS, Email, Facebook Messenger, Apple Messages for Business, Live Chat. [cite:2]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Custom event","def":"Voice only, for scripted and autonomous agents, as of that article. Syntax for an expression is the flow variable form the article prints. [cite:2]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Global_Language","def":"Set before Virtual Agent V2 to override the Studio language, for example fr-CA. [cite:2]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"UCCX Alpha","def":"ncs9r37 lists UCCX as an Alpha consumer of scripted and autonomous agents, beside WxCC, WxCCE, UCCE, and PCCE. [cite:3]","room":"T8-R05","href":"rooms/T8-R05-ai-wxcc.html#eco"},{"term":"Active sites","def":"n7s6ed7 Table 1, header August 18, 2026: the Sites row, attribute Active, maximum 300.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Active entry points","def":"n7s6ed7 Table 1: Entry points, attribute Active, maximum 6000.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Team-based routing queues","def":"n7s6ed7 Table 1: Queues, Team-based routing type, maximum 10500. A different cell, Contact service queue Inbound, is 11000.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Inbound contact service queue","def":"n7s6ed7 Table 1: Contact service queue, Inbound, 11000. Do not collapse that cell into the 10500 team-based queue row.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Active users","def":"n7s6ed7 Table 1: Users, Active, 20000. The footnote says Webex Contact Center supports unlimited concurrent agents at the organization level.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Capacity-based team number","def":"n7s6ed7 Table 3: Maximum number for a Capacity-Based Team is 100. That label is not an agent-per-team cap.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Capacity-based team count","def":"n7s6ed7 Table 3: Maximum Capacity-Based Teams for an organization is 50.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Capacity-based concurrent calls","def":"n7s6ed7 Table 3: Maximum number of concurrent calls for Capacity-Based Teams is 5000.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Queue Contact self-loop","def":"T3-R01 does not print a Queue Contact self-loop. n7s6ed7 in that room prints active sites 300, active entry points 6000, team-based queues 10500, and capacity-based Table 3 cells of 100, 50, and 5000.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Search FROM window","def":"The Search API says the FROM parameter cannot be older than 36 months from the current time. The duration between to and from must not be more than 365 days.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Search scopes","def":"The Search API requires scope cjp:config or cjp:config_read, and role Administrator or Supervisor.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Example search host","def":"The Search reference curl uses https://api.wxcc-us1.cisco.com. T3-R01 does not treat that host as every tenant’s host.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Contact Center residency row","def":"oybc4fb, header September 24, 2026: the Webex Contact Center row is checked for US, EU, Canada, UK, Japan, Australia, Singapore, and India. Saudi Arabia is blank on that row.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Country of Operation path","def":"oybc4fb: confirm Contact Center residency at Contact Center > Settings > Service Details > Country of Operation.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Architecture email channels","def":"utqcm7 lists email channels Gmail and Office 365. Messaging channels on that page are a separate list.","room":"T3-R01","href":"rooms/T3-R01-wxcc-multitenant-overview.html#limits"},{"term":"Discovery tool v3.5","def":"0hd75db, header June 27, 2025: download the discovery tool v3.5. The printed command is java -jar uccx-to-webexcc-v3.4.jar.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"CCX default port","def":"0hd75db: if you do not specify the port, the console uses 443. The tool needs Java 8 or above.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Bulk CSV row cap","def":"0hd75db: bulk operations limit any import CSV file to 5000 rows. Split a file that exceeds that limit.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Flow Control","def":"nb2ve0e: create routing strategies using the new Flow Control application. Legacy routing strategies are not copied because they are incompatible.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"DN–EP pair","def":"nb2ve0e: you can move an existing Dialed Number (DN) – Entry Point (EP) combination from the legacy platform to the new platform. That sentence is inside Webex Contact Center 1.0.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#eco"},{"term":"Legacy portal freeze","def":"nb2ve0e: while Pre-Upgrade setup is executing, do not make configuration changes on the legacy Management Portal. Changes may not be copied.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#quiz"},{"term":"Routing-control flag","def":"n2puc5z: if the Migrate Routing Controls parameter is 1, the tool deletes all existing routing controls of all types on the target before it copies.","room":"T6-R04","href":"rooms/T6-R04-ucce-pcce-to-wxcc.html#selfq"},{"term":"Assigned locations","def":"760wbi, header August 05, 2026: a Webex Calling administrator can administer up to 250 assigned locations. The delegation drop-down selects up to five. This is not an organization-wide location cap.","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#limits"},{"term":"Devices port cell","def":"b2exve: phone signaling source ports 5060–5280 sit under SIP TLS. The parent protocol cell is TCP. The devices protocol cell is blank.","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#flow"},{"term":"Certificate destination","def":"b2exve: certificate-trunk signaling destination TCP 5062. Registration-trunk destination TCP 8934.","room":"T7-R01","href":"rooms/T7-R01-sip-fundamentals-webex.html#flow"},{"term":"MyE911 host","def":"mwjlgk, header September 03, 2025: the RedSky Cirrus Cloud Host is https://wxc.e911cloud.com. That agent article does not reprint the September 08, 2024 admin steps.","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#flow"},{"term":"Calling E2EE path","def":"5h5d8ab: Services > Calling > Settings > Webex App tab > Security, Enable end-end encryption when making calls. Disabled by default.","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#config"},{"term":"Recording and E2EE","def":"5h5d8ab: call recording makes the service process media, so Calling E2EE is disabled.","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#core"},{"term":"Zero-trust meeting size","def":"5h5d8ab: zero-trust meetings use MLS and are up to 1000 participants. PSTN and SIP devices are excluded.","room":"T2-R06","href":"rooms/T2-R06-calling-security-compliance.html#limits"},{"term":"Extension length","def":"njvdjf2: internal extension length is 2–10 digits, default 4. Lengthening it does not rewrite existing speed dials to internal extensions.","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Route group size","def":"n0xb944: a route group holds 1 to 10 trunks.","room":"T2-R03","href":"rooms/T2-R03-dial-plans-pstn-routing.html#eco"},{"term":"Troubleshooting days","def":"frj1efb: Monitoring → Troubleshooting shows the past 21 days.","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#limits"},{"term":"Troubleshooting CSV","def":"frj1efb: export is up to 100 records for the tab you are on.","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#config"},{"term":"Client log retention","def":"z84p2bb: uploaded Webex App logs are available for 30 days. Collection requires the user to be online.","room":"T1-R06","href":"rooms/T1-R06-analytics-troubleshooting.html#limits"},{"term":"SP-initiated test","def":"nyx7kubb: do not test SSO from the IdP. Webex supports service-provider-initiated flows. Use the Control Hub SSO test.","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#eco"},{"term":"CDR role sunset","def":"Webex Calling Detailed Call History API access is obsolete for new assignment and stays operational until December 31, 2026.","room":"T1-R01","href":"rooms/T1-R01-control-hub-foundations.html#quiz"},{"term":"Historical Analyzer session","def":"tajemk: a historical report stays active 8 hours. A new real-time report defaults to a 5-second refresh, from 5 to 60 in steps of 5.","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#limits"},{"term":"Widget clocks","def":"n6m0w9z: the agent-statistics widget updates history every 24 hours and real-time every 60 seconds.","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#limits"},{"term":"Duration list gap","def":"tajemk Details lists None, 5, 15, or 30 minutes, and Start of Day. The create table also prints 10 minutes and Custom. T3-R07 does not collapse those lists.","room":"T3-R07","href":"rooms/T3-R07-analyzer-reporting.html#core"},{"term":"Table 5 bands","def":"t9xctu Table 5, as of 2026-10-14: up to 250 concurrent prefers registration OTT; about 250–2000 prefers certificate OTT; about 2000–6500 prefers certificate interconnect.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#limits"},{"term":"Premises and cloud PSTN","def":"n0xb944: calls that originate from premises users cannot use cloud PSTN.","room":"T6-R01","href":"rooms/T6-R01-enterprise-cutover-capstone.html#eco"},{"term":"Agent queue cap","def":"ubg5qd: an agent-assignment queue holds up to 1000 agents. That is not a team-queue cap and not a tenant cap.","room":"T3-R03","href":"rooms/T3-R03-entry-points-queues-routing.html#limits"},{"term":"Set Contact Priority","def":"Flow Designer toggle and activity. Static P1 (highest) through P9 (lowest). Unset or out of range 1–9 becomes 10. This is the VIP pattern. There is no separate VIP flag in nhovcy4.","room":"T8-R02","href":"rooms/T8-R02-flow-design-patterns.html#core"},{"term":"Callback Default Entry Point","def":"Control Hub Channel Settings entry point. A scheduled callback’s new interaction follows the flow linked there. np2fdx, header October 01, 2026.","room":"T8-R02","href":"rooms/T8-R02-flow-design-patterns.html#config"},{"term":"CCPP hop","def":"Off-net media relayed through a Cloud Connected PSTN provider. Distinct from a Local Gateway hop. PSTN receive metrics are not transmitted to the Webex Calling cloud. frj1efb.","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#core"},{"term":"LocalGatewayLoop","def":"A Troubleshooting refusal code: a loop between the local gateway and Webex Calling. frj1efb.","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#trouble"},{"term":"Lightning App","def":"The Salesforce UI the connector supports. Classic mode is not supported. Editions are Development, Enterprise, and Ultimate.","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#core"},{"term":"Openframe","def":"The ServiceNow plugin that hosts the gadget on the modern Agent Workspace. The legacy workspace is unsupported starting with Xanadu.","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#eco"},{"term":"CAMPAIGN_CRM_ID","def":"The campaign identifier these connector articles require. Salesforce stops at this field. Dynamics and ServiceNow also require CAMPAIGN_CRM_TABLE.","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#limits"},{"term":"Desktop Profile timeout","def":"The custom Desktop Profile Desktop Timeout can log the CRM connector out. The tenant Desktop Inactivity Timeout does not.","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#core"},{"term":"Phased migration","def":"Users move in groups. Until the last group moves, some users are on Unified CM and some are on Webex Calling. Each group requires dial-plan updates on Unified CM, Webex Calling, and the Local Gateway. [cite:1]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Single-step migration","def":"nw9po3o: the user moves from Jabber to the Webex App at the same time the calling service moves from Unified CM to Webex Calling. [cite:1]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Dual-step migration","def":"Step 1 moves the soft client to the Webex App and leaves calling on Unified CM. Step 2 moves calling. nw9po3o recommends this for larger customers who want those changes separated. [cite:1]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Webex Calling partition","def":"A Unified CM partition that holds +E.164 route patterns for destinations that now live on Webex Calling. The Local Gateway trunk’s inbound calling search space must not contain it. [cite:2]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Fixed extension length","def":"nqojzwt: every extension in a Webex Calling deployment has the same length. Internal extension length in Control Hub can be any value between two and ten. [cite:2]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Abbreviated inter-site dialing","def":"Extension dialing between locations works only when the dialed extension is unique. Overlaps need a steering digit and a site code. [cite:2]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Steering digit","def":"The first digit of the routing prefix for abbreviated enterprise inter-location dialing. nqojzwt says to avoid overlap with the first digit of any location and with location outbound dial digits. [cite:2]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Local Gateway","def":"q0pgpb: one or more Local Gateways are required if the organization keeps hybrid dual call control, so Webex Calling and Unified CM endpoints can call each other and so on-premises PSTN can be used. [cite:3]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Shared feature","def":"A feature whose members must stay together. q0pgpb names call queues. Hunt groups are in the same dependency list in that section. [cite:3]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Calls to On-Premises Extensions","def":"A per-location Control Hub setting. Unknown extensions of calling-number length 2–10 digits route to a PBX on an existing trunk or route group. [cite:6]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Cloud PSTN boundary","def":"n0xb944: Cloud PSTN, Cisco PSTN or Cloud Connected PSTN, provides PSTN access for Webex Calling users. Calls originating from premises users cannot access cloud PSTN. [cite:6]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Route group","def":"One to ten trunks. Trunks at the same priority share calls at random. If the higher-priority trunks are unavailable, the call uses a lower priority. [cite:6]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"WXC-DI trunk","def":"2vpf1: one SIP trunk to each Dedicated Instance data center in a region, for basic interop. Default trunks created by Cisco. The article says they should not be modified or deleted. [cite:4]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Interop location","def":"2vpf1: a location is mandatory to activate the interop SIP trunk. A PSTN connection and a main number are required. Without the main number, users cannot make or receive calls through the route group for that location. Premise-based PSTN is allowed when you are not using CCPP. [cite:4]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Certificate interop","def":"ofrt6u: the preconfigured SIP connectivity between Dedicated Instance and multi-tenant is certificate-based and rides the Cisco Webex backbone. Those trunks have to be activated before calls work. [cite:7]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Contiguous numbers","def":"ny65x1bb recommends keeping contiguous phone numbers on the same call control when you split users between multi-tenant and Dedicated Instance. [cite:5]","room":"T6-R07","href":"rooms/T6-R07-coexistence-interop.html#eco"},{"term":"Pro Pack window","def":"13 months of Calling analytics for calls based in Webex App. Without Pro Pack, 3 months. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"3-month picker","def":"From January 27, 2026 the maximum selectable range is 3 months at a time. Longer history still requires multiple reports. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Per-call KPI","def":"Alice calling Bob is one call for Detailed Call History KPIs, even when the call has several legs. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Originating record","def":"The leg from the calling registered user’s point of view. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Terminating record","def":"The leg from the called registered user’s point of view. A PSTN caller produces only this row for the called user. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Good media session","def":"Both audio and video under 150 ms jitter, 400 ms latency, and 5% packet loss. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Bounced call","def":"Presented to an agent and not answered. A declined call is not counted as bounced. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Call on Webex","def":"Not included on the detailed call history tab. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"External unknown","def":"CDRs with unknown call type are accounted as external calls. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Correlation id split","def":"Consultative transfer, call park, and call retrieve count as an additional internal call because the correlation id differs. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"21-day cross-launch","def":"Worst calling experience opens Troubleshooting for at most 21 days. [cite:1]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Partner CDR webhook","def":"n5zr85e: multi-tenant partners receive detailed call history records every 5 minutes. Header date was not in the extract. re-check [cite:2]","room":"T2-R08","href":"rooms/T2-R08-calling-analytics-cdr.html#eco"},{"term":"Services setup wizard","def":"The Control Hub wizard for a trial or a mapped subscription. It reappears until setup completes. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Country of operation","def":"Chooses the data center. Not editable after confirm. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Data Locality","def":"The article the wizard points at for country-to-data-center mapping. The same list is called out for on-premises and Webex Contact Center Enterprise in nee1mb6. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Common Edge","def":"The telephony section’s name for the shared edge between Webex Calling and Webex Contact Center. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Welcome email","def":"Sent to the address on the trial or order wizard. Get Started sets the password. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Order summary","def":"Download Order Summary after Submit, then Close. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Solution Assurance","def":"Who you contact if Save reports an incompatible location. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Webex Connect order","def":"The later block says have a Connect or Google CCAI hybrid order before that begin-state. [cite:1]","room":"T3-R02","href":"rooms/T3-R02-tenant-provisioning-setup.html#eco"},{"term":"Common Edge","def":"Shared edge. New subscriptions include Webex Calling PSTN services for it. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Webex Contact Center PSTN","def":"Cisco-billed bundle for contiguous United States and Canada. No international dialing. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Cloud Connected PSTN","def":"Certified providers. The article says over 65 countries. +E.164. re-check [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Local Gateway","def":"Customer SBC. The article says over 140 markets, OTT or Edge Connect. re-check [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Cisco Calling Plan","def":"Trials and regions where Cisco supports service and/or inbound toll-free numbers, in this article. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"WebRTC desktop","def":"Browser media. No local gateway required. Unavailable for the Japan data center. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Dial Number","def":"Login destination. Typically +E.164, not mandatory, must be reachable. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Extension","def":"Matched to a registered Webex Calling endpoint. Match enables preferred device. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Desktop","def":"The login name for WebRTC. [cite:1]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Location main number","def":"gsmsaeb: it does not appear in the Webex Calling available-number list for entry-point mapping. [cite:2]","room":"T3-R05","href":"rooms/T3-R05-voice-options.html#eco"},{"term":"Controlled GA","def":"Only customers who planned onboarding with Cisco Solution Assurance. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"7-day Connect window","def":"New administrators open Webex Connect within 7 days or recreate the account. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"Webex CC Task node","def":"Must be Authorized, with the Engage node, before channel setup. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"Social Channel","def":"The entry-point channel type in the setup section, with a Social Channel Type and an asset. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"QueueTask","def":"Connect node for skill requirements, relaxations, and Contact Priority. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"Skill profile on a team","def":"Not supported, in the sentence dated with the August 19, 2026 article. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"Unknown file","def":"How Agent Desktop shows an attachment the malware scan dropped. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"WABA","def":"WhatsApp Business account number, obtained with the account manager. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"AMB","def":"Apple Messages for Business. MSP selection is Webex Connect. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"New Digital Channels","def":"Management Portal launch to the default admin console. [cite:1]","room":"T3-R06","href":"rooms/T3-R06-digital-channels.html#eco"},{"term":"Supervisor + Agent","def":"Supervisor license, no administrator role, station credential Supervisor and Agent. [cite:1]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Supervisor only","def":"Same license, station credential Supervisor only. No My Workspace. [cite:1]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Licensed administrator","def":"Premium Agent license plus full administrator or Contact Center Service administrator. [cite:1]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Unlicensed administrator","def":"Administrator role and no contact-center agent license. [cite:1]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Listen","def":"One agent. Disabled if another supervisor is already monitoring. [cite:2]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Barge In","def":"Only after listening starts. Not during consultation. [cite:2]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Interactions page","def":"Where monitoring and barge controls live now. [cite:2]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"500 agents","def":"Maximum when a listening schedule names specific agents. [cite:3]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Six months","def":"How far the listening schedule’s end can extend, in 5k9gxcb. [cite:3]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"Weekly coaching","def":"okxzd1: recommendations generate weekly once team thresholds exist. [cite:1]","room":"T3-R08","href":"rooms/T3-R08-supervisor-experience.html#eco"},{"term":"A-FLEX-AI-QM","def":"The AI Quality Management add-on SKU 6m6r3fb names. [cite:1]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"A-FLEX-AI-QMMB","def":"The AI Assistant and AI Quality Management bundle SKU. [cite:1]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"Org-level features","def":"Evaluations and speech analytics, and Coaching Insights. [cite:1]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"Queue-level features","def":"Sentiment analysis and real-time transcriptions, in the scope column. [cite:1]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"AgentAnswered","def":"The event that the all-queue transcription path places Start Media Stream after. [cite:1]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"RT_TRANSCRIPT","def":"The custom-layout visibility value for the transcription tab. [cite:1]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"Basic WFM","def":"The lighter workforce package on nmzg380. Header August 13, 2025. [cite:2]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"Basic QM","def":"The lighter quality package. Live screen monitoring is on the existing column, not the Basic column. [cite:2]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"py6u9h boundary","def":"Enterprise WFO SKU strings were not re-fetched. TODO-verify before you paste them here. [cite:3]","room":"T3-R09","href":"rooms/T3-R09-wfo-ai-features.html#eco"},{"term":"Router","def":"Runs the script and picks the target. Both sides stay in service. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"Logger","def":"First store for historical data, and the authoritative configuration database. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"Central Controller","def":"Router and Logger, often co-located. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"MDS","def":"Message Delivery Service. Feeds both sides the same messages in the same order. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"PG","def":"Normalizes the peripheral and tracks agent or task state. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"PIM","def":"Peripheral Interface Manager. One side active. Not lock-step. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"OPC","def":"Open Peripheral Controller. Lock-step. Primary agent state for a Unified CM PG. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"GED-125","def":"VRU PIM protocol. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"GED-188","def":"CTI Server protocol. Direct desktop use is deprecated in this chapter. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"AW-HDS","def":"Configuration, real-time, and historical data, no call detail. CUIC’s standard source. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"CUIC Controller","def":"The mandatory publisher. Includes a Member. Administration runs here. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"Finesse gap","def":"Not named in this chapter. TODO-verify. [cite:1]","room":"T4-R02","href":"rooms/T4-R02-core-components.html#eco"},{"term":"Routing client","def":"Asks for a route and delivers the call. An IXC or a peripheral. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Pre-routing","def":"IXC asks for the initial destination. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Post-routing","def":"The peripheral asks to refine or redirect. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Call type","def":"Voice: DN, CED, CLID. Non-voice: Script Type Selector and two application strings. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Skill target","def":"A service, skill group, or agent. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Route","def":"Skill target plus service. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Label","def":"What the routing client maps to a destination. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Default label","def":"On the dialed number, used when call type or destination lookup fails. [cite:1]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Type 10 VRU","def":"Serves both the switch leg and the VRU leg in the Comprehensive ICME model. [cite:2]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"SendToVRU","def":"The Script Editor node that connects the call to the Network VRU. [cite:2]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Basic CVP level","def":"Wav files and DTMF. [cite:2]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Advanced CVP level","def":"ASR/TTS and VXML Server applications. [cite:2]","room":"T4-R03","href":"rooms/T4-R03-call-flow-wxcce.html#eco"},{"term":"Routing script","def":"The File, New choice that opens on a Start node and returns a destination. [cite:1]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Administrative script","def":"The other File, New choice. This room does not invent its node list. [cite:1]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Call Type Manager","def":"Script menu. Schedules tab binds a script to a call type and a period. [cite:1]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Type 10 two-step","def":"Transfer to CVP, then an automatic VRU leg on VVB or the VXML gateway. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Send to VRU","def":"Connects the call to the Network VRU. Sometimes implied by an earlier node. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Run External Script","def":"Tells the VRU which Network VRU script to run. Success and failure branches. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Call.VRUStatus 2","def":"On the failure branch, the guide says the VRU is likely not functioning. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"20 seconds","def":"Routing client did not respond to the last Send To VRU or Translation Route to VRU. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"30 seconds","def":"The sample announcement interval between Wait and Run External Script. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Interruptible node","def":"Wait, and an interruptible Run External Script. Other nodes are uninterruptible. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Queue node","def":"Marks the call queued and exits. It does not play audio. [cite:2]","room":"T4-R04","href":"rooms/T4-R04-scripting-icm-routing.html#eco"},{"term":"Acceptance testing","def":"q0pgpb’s validation after migration. Examples, not a complete checklist. [cite:1]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Subset test","def":"After a group moves, test a subset of those users, and test call queues and hunt groups that moved with them. [cite:1]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Pilot tools","def":"Use the same migration tools in the pilot that you will use for the rest of the organization. [cite:1]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"PIDF-LO address","def":"For each US or Canada location, q0pgpb says enter a street address. The platform validates it and uses it for PIDF-LO on emergency calls. [cite:1]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Verify Call Routing","def":"Control Hub simulation. Path: Services > PSTN & Routing > Gateway configurations, then Verify Call Routing. Cisco Calling Plan customers can open Services > Calling > Call Routing. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Call source","def":"A cloud user, workspace, virtual line, or premises trunk. Then a number or URI, then See Routing Result. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Routing result contents","def":"Outgoing call permissions, fraud prevention, digit patterns, call intercept, and translation patterns. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Troubleshooting view","def":"Monitoring place for one Webex Calling call’s connectivity and media. Calls appear after they end. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"21 days","def":"frj1efb: view calls for the past 21 days. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Call segment","def":"A point-to-point connection inside a call. An auto attendant deflection is two segments in the article’s Alice example. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Correlation ID","def":"Ties segments of the same call. Searching by correlation ID or phone number shows the Webex Calling tab. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Hop","def":"The hop detail shows where media went, including whether ICE kept media off the cloud relay. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Quality grades","def":"Poor, Good, or None / Not available. Poor means caller or callee had a poor end-to-end experience. Meetings and Call on Webex are not graded this way. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"CSV export","def":"Up to 100 troubleshooting call records per CSV file, for the tab you are on. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"JSON call report","def":"From the call details page, with participant details as CSV. [cite:3]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Decommission order","def":"This room does not quote an optimize-phase decommission sequence. TODO-verify against the English optimize article before you teach one.","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Acceptance test","def":"The implement article’s sample checks after a group moves. The article says the section is not exhaustive. [cite:1]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Transit role","def":"After users and endpoints are on Webex Calling, Unified CM can remain only to pass calls between PSTN gateways and Webex Calling through the Local Gateway. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Hidden partition","def":"Where the guide says to place migrated directory numbers so search spaces prefer the cloud path. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Cloud Connect cutover","def":"The four-step move of premises PSTN onto a Cloud Connect partner, including a disposable test location. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"Horizon Mobility","def":"The name the December 2025 guide prints for the dispatchable-location product you update when the building network changes. [cite:2]","room":"T6-R08","href":"rooms/T6-R08-post-migration-validation.html#eco"},{"term":"VXML Server","def":"J2EE server that runs dynamic VoiceXML applications. Standalone install does not include the Call Server. [cite:2]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Call Studio","def":"The tool that creates the application deployed to the VXML Server. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Cisco VVB","def":"Virtualized Voice Browser. In the standalone figure it receives the SIP invite and requests VoiceXML over HTTP. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Switch leg","def":"Comprehensive leg where the gateway does TDM-to-VoIP and call switching. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"VRU leg","def":"Comprehensive leg where Cisco VVB provides VRU voice treatment. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Micro-application","def":"VoiceXML pages the VXML Server creates for Unified CVP microapplications after the 11.5(1) move. [cite:2]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"SendToVRU","def":"ICM Script Editor node the comprehensive ICME section names for connecting the call to the Network VRU. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Type 10","def":"Network VRU type that serves both the switch leg and the VRU leg in the comprehensive ICME model. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"ReqICMLabel","def":"Call Studio decision element used when a standalone script looks up a label in ICM. [cite:1]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Flow Designer","def":"The build-and-manage article is for Webex Contact Center flows. It is not the Call Studio chapter. [cite:6]","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Hybrid IVR","def":"The July 2023 Webex CCE note: traditional ASR/TTS/CRM plus Dialogflow CX, with some nodes on premises and some in the cloud. [cite:5] re-check","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"CVP on Webex CCE","def":"January 2025 what’s-new: custom code applications, including CVP applications, can be hosted on Webex CCE. [cite:5] re-check","room":"T4-R05","href":"rooms/T4-R05-cvp-vxml-ivr.html#eco"},{"term":"Finesse","def":"The OpenSocial gadget container documented in the Cisco Finesse Administration Guide, Release 15.0(1). [cite:1]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"Manage Desktop Layout","def":"The administration gadget used to upload the XML layout for agents and supervisors. [cite:1]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"3rdpartygadget","def":"The web application on the Finesse server that hosts uploaded third-party gadget files. [cite:1]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"Shindig","def":"The backend that proxies gadget REST calls so the browser does not make a cross-origin call directly. [cite:1]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"CTI server","def":"Runs on the peripheral gateway. Finesse is configured with an A side and a B side. [cite:5]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"Peripheral ID","def":"The Agent PG routing client ID. The guide says it should be the same value for the A-side and B-side CTI servers. [cite:5]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"OUT_OF_SERVICE","def":"Finesse state while CTI failover is in progress. [cite:4]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"IN_SERVICE","def":"Finesse state after it reconnects to a CTI server and will again answer clients and publish events. [cite:4]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"Manage Digital Channels","def":"A gadget path the default layout comments include for digital channels. The what’s-new page points at the gadget user guide. [cite:1] [cite:7]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"FIPPA","def":"Finesse IP Phone Agent. The March 2022 VPN-less note says FIPPA is not supported on that internet path. [cite:7] re-check","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"Multi-tenant Agent Desktop","def":"The Webex Contact Center desktop in T3-R04. It is not this XML layout. [cite:8]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"Conference caveat","def":"An agent on a conference with devices that are not other agents or supervisors can see unpredictable desktop notifications across a failover. Phone operations can continue. The desktop returns to usual after the agent drops the conference. [cite:4]","room":"T4-R06","href":"rooms/T4-R06-finesse-desktop-gadgets.html#eco"},{"term":"CUIC","def":"Cisco Unified Intelligence Center. The reporting application in the Unified CCE reporting user guide. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Stock report","def":"A Cisco-provided template you download and import. It shows data saved in the Unified CCE database. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Live Data","def":"Reports whose data source is the Live Data stream. Refresh is usually less than every 3 seconds. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Realtime template","def":"A stock Realtime report. The guide says it is slower than Live Data. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Historical template","def":"A stock Historical report over saved database data. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Grid view","def":"The default tabular view. Every stock report has one. [cite:2]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Save As","def":"The way the user guide says you clone a stock template before you customize it. [cite:2]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Report definition","def":"How the user guide describes the query, fields, filters, and refresh behind a report template. [cite:2]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Analyzer","def":"The multi-tenant Webex Contact Center reporting surface. Not this CUIC chapter. [cite:3]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"All Users group","def":"A February 2022 what’s-new line: non-administrative owners can see the All Users group in the CUIC permission modal on Webex CCE. [cite:5] re-check","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"WCAG 2.1","def":"The reporting chapter says CUIC adopts Level A and Level AA. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"1366×768","def":"The minimum screen resolution that chapter lists for CUIC. [cite:1]","room":"T4-R07","href":"rooms/T4-R07-reporting-cuic.html#eco"},{"term":"Side A and Side B","def":"The two redundant instances. Not a load-balance pair. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Private network","def":"Separate physical network for synchronization, MDS, and state transfer after isolation. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Public network","def":"Separate path between Central Controllers and PGs. Also the path that lets fault tolerance tell a dead component from a dead network. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Device majority","def":"The test a router runs when it loses its peer. Side A: at least half the enabled PGs. Side B: more than half. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Isolated-enabled","def":"The router keeps handling traffic because it has device majority. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Isolated-disabled","def":"The router stops processing because it does not have device majority. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Config_Message_Log","def":"14-day retention. Inside that window, logger resync is automatic when the private network returns. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Hot standby PG","def":"One side active. The other takes over and runs stand-alone until redundancy returns. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Finesse 2,000","def":"The design guide’s per-cluster user maximum tied to the CTI server maximum. Both servers together stay at or under 2,000. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Reference design names","def":"2000 Agent, 4000 Agent, and 12,000 Agent appear in the QoS paragraph. They are not the Webex CCE what’s-new figure. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"48,000 agents","def":"January 2025 what’s-new: Webex CCE supports 48,000 concurrent agents and 300 calls per second on a single tenant. [cite:2] re-check","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"TCD","def":"The record the PG creates when a call fails because the public WAN voice path failed. [cite:1]","room":"T4-R08","href":"rooms/T4-R08-sizing-ha.html#eco"},{"term":"Router","def":"Selects a peripheral or agent for an inbound contact. Both sides stay in service and share data through MDS. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"Logger","def":"Stores configuration, real-time, and historical data. Hears only its own Router. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"Central Controller","def":"A Router and Logger combination. Often collocated on one server. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"PG","def":"Talks to the telephony device, tracks agent and call state, and forwards routing requests. Duplexed with MDS, with one side active for many components. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"PIM","def":"Peripheral Interface Manager. Not lock-step. One side is active per peripheral. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"OPC","def":"Open Peripheral Controller. Critical PG process. Kept in lock-step with the other side. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"Administration & Data Server","def":"Configuration copy, real-time interface, historical data server platform, and the Script Editor interface. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"HDS","def":"Optional Historical Data Server. Long-term repository. Offloads historical reporting from the Logger. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"SendToVRU","def":"ICM Script Editor node that connects the call to the Network VRU. [cite:2]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"VRU PG and MR PG","def":"These PGs do not maintain agent state. They maintain call or task state and expose an interface for instructions from the Router. [cite:1]","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"Classroom session","def":"TODO-verify . No session number is stored in this room.","room":"T4-R09","href":"rooms/T4-R09-classroom-index.html#eco"},{"term":"SBC Peering Hybrid Model","def":"One of two March 2022 model names. Internals are in the partner technical guide, not in this room. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Localized RTP Hybrid Model","def":"The other March 2022 model name. Same deferral. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Hybrid IVR","def":"July 2023. On-premises ASR, TTS, and CRM plus Dialogflow CX. OTP is the on-premises example. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Regional media","def":"July 2024. Audio and SIP signaling stay in the geographic region. Control signals may go to the tenant home. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Enhanced media platform","def":"The tenant capability the July 2024 note says must be enabled before the no-extra-cost regional media line applies. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"VPN-less Finesse","def":"March 2022 internet access to the desktop. FIPPA unsupported. Multiple devices through NAT unsupported. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Webex Connect","def":"Digital channels named on nhy3hvdb. The July 2023 list and the January 2025 list are not the same length. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Custom CVP hosting","def":"January 2025. Custom code and CVP applications can be hosted on Webex CCE, using VXML and Call servers, without the article claiming calls are disrupted. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Monitoring Dashboard","def":"January 2025. Call Error, Call Detail, CDR, CMR, and agent device status. User guide is linked from the article. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Edge Connect","def":"Current article n68tcpb, September 17, 2026: private peering to Meetings, Calling, and Webex Contact Center Enterprise data centers. [cite:2]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"CSA STAR Level 1","def":"September 2022 certification statement on the what’s-new page. [cite:1]","room":"T4-R10","href":"rooms/T4-R10-hybrid-cloud-connected.html#eco"},{"term":"Dedicated Instance","def":"Dedicated cloud instance based on Unified CM, integrated with Webex Calling, sold as an add-on. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Knowledge Worker","def":"Count captured in the First Time Setup Wizard. Drives call-processing nodes, Unity Connection, and Expressway entitlements. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Common Area device","def":"The other First Time Setup Wizard count that drives call-processing node count. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Full-size cluster","def":"Up to 8 call-processing servers or about 50,000 devices on version 14 and above. The configuration limit stated to the partner is 50,000 configured devices. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"160,000 end users","def":"Maximum that may be configured or synchronized over LDAP. They may be active or present only for directory or service discovery. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Not harmonized","def":"Dedicated Instance and Webex Calling keep different calling features. Hunt-group membership does not cross. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"A2Q","def":"Required for multi-cluster provisioning and activation. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Additional clusters SKU","def":"The article’s name is “Additional Webex Calling Dedicated Instance Clusters.” It grants Unified CM, IM and Presence, Unity Connection, Expressways, and Emergency Responder. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"WXC-DI trunks","def":"Default multi-tenant interop trunks, one toward each Dedicated Instance data center in the region. Do not modify or delete them. [cite:2] re-check","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"DRS backup","def":"Nightly. Latest three kept. Password protected. Restore only. No customer access. [cite:1]","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Expressway-E call policy","def":"Preconfigured to block all inbound B2B calls. Update it during B2B testing so calls come from valid sources. [cite:2] re-check","room":"T5-R01","href":"rooms/T5-R01-what-dedicated-instance-is.html#eco"},{"term":"Partner Connect","def":"Partner-aggregated private connection. Direct cross-connect or Equinix Fabric. [cite:1]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Direct cross-connect","def":"Physical connection at Equinix. Charge is the physical connection. Two points per listed geo. 1 G or 10 G. [cite:1]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Equinix Fabric","def":"Virtual connection. Charge for the physical connection and each virtual connection, one virtual connection per customer. 200 MB to 10 GB. [cite:1]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Dot1Q","def":"Partner gear must support Layer 3 subinterfaces with dot1q. The partner provides a tag when activating a customer. [cite:1]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Virtual Connect","def":"Two GRE-over-IPsec tunnels per region over the customer’s internet. Hub design. [cite:2]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Dual-tier headend","def":"Virtual Connect routing and GRE on one device, IPsec on another. [cite:2]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"/25 per data center","def":"Cisco splits the assigned /24 into two /25s and advertises each over its tunnel. [cite:2]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Edge Connect","def":"Private peering that bypasses the public Internet. Equinix or Megaport. ASN 13445. [cite:3]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Link-priority community","def":"13445:200 through 13445:900. 900 is the most desirable path. AS-path prepending is not supported with private ASNs. [cite:3]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"Edge Connect 3.0","def":"The customer-story article says one peering capability can carry multi-tenant, Dedicated Instance, and Meetings. Two sites in the region are still required. [cite:4]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"BFD","def":"Default 300 ms times 3 on Edge Connect for Dedicated Instance links, and the same default on Meetings and Calling links. [cite:3]","room":"T5-R03","href":"rooms/T5-R03-connectivity-options.html#eco"},{"term":"voice class codec 100","def":"jr1i3r’s filter. Preference 1 is g711ulaw. Preference 2 is g711alaw. [cite:1]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"Additional codec","def":"The article allows more types when both the originating and terminating systems support them. [cite:1]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"DSP transcoding","def":"Supported for more complex designs. Not included in the Local Gateway guide. [cite:1]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"voice translation-rule","def":"Global rule set. 64020 defines it before the profile. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"voice translation-profile","def":"Binds a translation rule with translate called, translate calling, or translate redirect-called. 64020 says redirect-called is the redirect DNIS, or the original called number. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"translation-profile incoming","def":"Number translation for an incoming VoIP call. Name length in that table is thirty-one characters. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"translation-profile outgoing","def":"Number translation for the outbound call. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"translate called","def":"The profile command that selects the rule for the called number. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"translate calling","def":"The profile command for the calling number. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"test voice translation-rule","def":"The exec command 64020 prints. Example input 5551234 against rule 1. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"call-block translation-profile","def":"A profile used to decide which inbound calls to reject. [cite:2]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"URI before called-number","def":"The CUBE dial-peer chapter lists URI class matches ahead of incoming called-number. [cite:3]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"211306","def":"The IOS call-routing support document. T7-R01 quotes its full inbound order. This room does not shorten that order to the CUBE chapter’s list. [cite:3]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"stun-usage 100","def":"jr1i3r’s ICE class on the Webex trunk. [cite:1]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"DS 64224","def":"High-CPU signature. At 75 percent it disables debugs and uninstalls diagnostic signatures. [cite:1]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"Sample secret","def":"The DS install steps show an FTP URL with a username and password. This Canon does not store that sample. [cite:1]","room":"T7-R02","href":"rooms/T7-R02-cube-deep-dive.html#eco"},{"term":"ICE","def":"Interactive Connectivity Establishment. The method nt6eyxb uses to find a direct media path. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"ICE-lite","def":"What CUBE supports. The article points at further restrictions on CUBE and does not paste them into the Webex page. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"STUN","def":"Session Traversal Utilities for NAT. Used to learn a server-reflexive address. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Candidate","def":"A local address or a server-reflexive address where the endpoint can receive media. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Reinvite","def":"The SIP request that starts media on the optimized path after checks succeed. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Default on","def":"Desk phones and Webex App. DECT and ATA are excluded. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Local Gateway command","def":"The article’s words are “STUN usage lite,” reviewed in the Local Gateway registration article. jr1i3r prints voice class stun-usage 100. [cite:1] [cite:2]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"CUBE minimum for this feature","def":"17.3 or 16.12.5, in nt6eyxb. That is not the trunk-registration minimum in t9xctu. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Same organization","def":"Calls optimize only inside one organization. Interorganization media goes through the PSTN for regulatory reasons. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Recording path","def":"Cloud path. Not optimized. [cite:1]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"G.711 class","def":"jr1i3r preference 1 g711ulaw, preference 2 g711alaw. [cite:2]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"SIP ALG","def":"b2exve recommends turning it off because some ALG implementations break firewall traversal even though signaling is encrypted. Revision line January 21, 2025. re-check [cite:3]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"NAT pool","def":"August 13, 2026 update: size the pool so users and devices are not stuck when ports run out. [cite:3]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"DSCP","def":"b2exve: Webex App audio Expedited Forwarding (46) on 8500–8599. Video Assured Forwarding 41 (34) on 8600–8699. Device signaling Class Selector 3 (24). [cite:3]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Certificate media return","def":"Call media from Webex Calling toward a certificate-based Local Gateway uses 19560–65535 UDP. [cite:3]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Phone source signaling","def":"Devices row 5060–5280 toward 8934. The September 07, 2026 history line expanded 5060–5080 to 5060–5280. [cite:3]","room":"T7-R03","href":"rooms/T7-R03-codecs-media-nat.html#eco"},{"term":"Trunk","def":"The connection from Webex Calling to a local gateway or other supported device. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Registration trunk","def":"The SBC registers. t9xctu: up to 250 concurrent calls, and the getting-started table limits that model to CUBE. [cite:3]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Certificate trunk","def":"You enter an FQDN. Webex trusts the gateway from that FQDN plus the certificate. Concurrent calls above 250 in the getting-started wording. Table 5 is a separate band table and is not flattened here. [cite:1] [cite:3]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Route group","def":"1 to 10 trunks, possibly from multiple locations. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Priority","def":"Same number means random distribution. Lower priority is the backup. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"SRV weight","def":"DNS records for the gateway FQDN. Differing weight and priority change distribution of calls from Webex Calling. Use the same listening port on those records. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"FQDN in the certificate","def":"CN or SAN must match the Control Hub FQDN, without the port. [cite:2]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Wildcard","def":"Not supported, in t9xctu. [cite:3]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Server Authentication EKU","def":"Supported alone. Client Authentication EKU is not required by Webex. Some third-party SBCs reject that certificate. [cite:2] [cite:3]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Two media PoPs","def":"Assigned at provisioning, via DNS SRV, inside the region. [cite:3]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"OPTIONS","def":"Error 7: OPTIONS sent to the Local Gateway got no response. Error 11: the gateway is not sending OPTIONS toward Webex. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"3 minutes","def":"Trunk status updates on that interval. Refresh is still manual if you want the page now. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Impaired versus all-proxy errors","def":"Impaired is one proxy. Errors 2, 6, 11, and 12 appear when every proxy is affected. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Calls to on-premises extensions","def":"Per location. Unknown extensions of 2–10 digits can use a trunk or route group. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Premises PSTN boundary","def":"Calls originating from premises users cannot access cloud PSTN. [cite:1]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"DI interop trunk","def":"Separate from a customer Local Gateway. ofrt6u activates the certificate trunk Cisco already created. [cite:4]","room":"T7-R04","href":"rooms/T7-R04-sip-trunk-design.html#eco"},{"term":"Longest Available","def":"Eligible agent who has been available the longest since the last contact. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Cross-media position","def":"Any offered media type clears the longest-available position on every channel. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Simultaneous offer","def":"np2fdx: a small possibility that one longest-available agent is routed multiple contacts queued to the same queue at the same time, because the architecture is distributed. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Circular","def":"Round-robin. The pointer moves to the next configured agent after a successful contact-surplus match. Parked contacts do not move that pointer. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Top-down","def":"Every contact starts at the first configured agent and walks down. No pointer. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Best Available","def":"Score from proficiency skills named in the requirement. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Inverted skill","def":"A <= condition uses 10 minus the agent’s value so a lower skill scores as a stronger match. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Weights","def":"Used in Best Available. Not used by Longest Available. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Unscored skills","def":"Boolean, text, and enum skills filter eligibility. They are not in the score. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Skill relaxation","def":"A later requirement overwrites the contact’s skill requirement on a timer so more agents can match. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Call distribution group","def":"Teams at a level. If nobody matches, the contact parks, then the next group’s teams are added. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Capacity-based team","def":"Voice to a DN and a capacity. No Agent Desktop. np2fdx names voicemail, answering machines, or hunt groups as the people or devices that answer. [cite:1]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Default on a team queue","def":"ubg5qd, page header October 08, 2026: for a non-skill queue with team assignment, Longest available is the default. For a non-skill queue with agent assignment, Circular is the default, and that queue can hold a maximum of 1,000 agents. [cite:3]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Hunt group path","def":"Control Hub Services > Calling > Features. [cite:2]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Advance after rings","def":"o6rfjeb: you can enable Advance after a set number of rings for the routing choice. [cite:2]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"AutoCSAT skill","def":"nv7abhz, page header October 08, 2026: AutoCSAT can be added as queue routing criteria, alone or with other skills. It is system-controlled. [cite:4]","room":"T7-R05","href":"rooms/T7-R05-queue-theory-contact-center.html#eco"},{"term":"Auto attendant","def":"The Calling object that provides IVR in the upg0eu table. [cite:1]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Call queue","def":"The Calling object that can add callers to a queue and show a specific caller ID number when the call is forwarded. [cite:1]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Hunt group","def":"A Calling feature that rings members in a chosen pattern. Path: Services > Calling > Features. [cite:2]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Shared line group","def":"The fourth column. It cannot take a workspace member and cannot route by priority and skill. [cite:1]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Longest Idle","def":"The hunt-group pattern. Not the Contact Center name Longest available. [cite:2]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Longest available","def":"ubg5qd’s default for a non-skill team queue, and one of two skill patterns. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Circular default","def":"ubg5qd chooses Circular for non-skill agent assignment. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Best available","def":"Highest proficiency among agents who meet the skill requirement. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Weight default","def":"If you do not configure a weight on Best Available, the article applies 1. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Queue name","def":"Cannot exceed 80 characters. Alphanumeric characters, underscores, and hyphens. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Channel type","def":"Chat, Email, Social channel, or Telephony. Inbound queues display Telephony by default. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Transfer to the same agent","def":"An optional toggle on the Queues list. It applies to all queues of the tenant. [cite:3]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"India caller ID","def":"For the hunt-group number as caller ID, the hunt group’s location and the agent’s location must use the same PSTN provider, country, and zone. [cite:2]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Pattern shrink","def":"Moving from a 1,000-member pattern to Weighted or Simultaneous keeps only the first 100 or 50 members. [cite:2]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Location hunt-group cap","def":"The maximum number of hunt groups for each location is 1,000. [cite:2]","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Enterprise selection","def":"Not defined on these pages. TODO-verify .","room":"T7-R06","href":"rooms/T7-R06-routing-strategies-compared.html#eco"},{"term":"Troubleshooting view","def":"Control Hub page for connectivity and media quality of Webex Calling calls. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"21 days","def":"How far back that view goes. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"After the call ends","def":"When a Webex Calling call appears. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Correlation ID","def":"Ties multiple segments of the same call. Filters are not available for a phone-number or correlation-ID search. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Call segment","def":"A direct hop between two participants. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Hop details","def":"Where the article tells you to look for where the issue could be. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Poor","def":"Caller or callee had a poor end-to-end experience. The example is choppy audio. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Good","def":"The end-to-end experience did not exceed thresholds. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"None","def":"No media quality data. The column also says Not available. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"ICE","def":"Media directly between users when optimization succeeds. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"PNC","def":"Private Network Connect, one of the path-optimization values. [cite:1]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Online","def":"Every edge proxy reached the Local Gateway. [cite:2]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Impaired","def":"At least one edge proxy did not. [cite:2]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Config Validation","def":"Registration-based managed gateways only. [cite:3]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"Two years","def":"How long 2zx7fg says validation results are stored. Gateway configuration data is removed after 8 hours. [cite:3]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"DS 64224","def":"High-CPU signature at 75 percent. [cite:4]","room":"T8-R06","href":"rooms/T8-R06-troubleshooting-methodology.html#eco"},{"term":"100 records","def":"The per-CSV cap for troubleshooting call records. [cite:1]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"JSON call report","def":"Downloaded from the call details page beside the participant CSV. [cite:1]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Participant CSV","def":"Participant details from that same page. [cite:1]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"PRT","def":"Problem report tool. A compressed set of support files, in n4hssfr’s words. [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Actively registered","def":"The MPP condition for on-demand collection. [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Report Problem","def":"The online MPP action. [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Manage device logs","def":"The DECT support action, and the offline MPP wording “Manage across Device Logs.” [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Handset required","def":"Remote DECT PRT needs a connected handset so the base has a SIP registration. [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Stored under the base","def":"The system stores all PRTs under the base station’s device ID. [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Standard","def":"One of the two DECT network logging levels. [cite:3]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Debug","def":"Granular PRT and syslog. Recommended only while diagnosing. [cite:3]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Whole network","def":"The selected level applies to the entire DECT network. [cite:3]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Restart warning","def":"If other configuration is queued, applying the logging change may restart base stations. [cite:3]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"DS 64224","def":"Disables debugs at 75 percent CPU. Sample FTP secret is not copied. [cite:4]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Helpdesk collection","def":"n4hssfr says TAC can collect logs through helpdesk. [cite:2]","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"Client log window","def":"Not quoted from a fetched article in this room. TODO-verify .","room":"T8-R07","href":"rooms/T8-R07-logs-and-tools.html#eco"},{"term":"October 13 logging","def":"DECT network level, Standard or Debug. [cite:1]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"October 7 list","def":"Armenia, Aruba, Azerbaijan, Botswana, Belize, Cambodia, Georgia, Guadeloupe, Guyana, Haiti, Moldova, Zambia. [cite:1]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Non-geographic and Cisco Calling Plan","def":"Not supported, in g1gtsdb. [cite:2]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Toll-free and Cisco Calling Plan","def":"U.S. and Canada locations only. [cite:2]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"BCIBTFTN","def":"The license g1gtsdb says to purchase before toll-free provisioning on Cisco Calling Plan. [cite:2]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Assignment ban","def":"Toll-free and restricted non-geographic numbers cannot be the number of a user, workspace, or virtual line. [cite:2]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Auto Answer","def":"September 29. Users, workspaces, virtual lines. A preferred device can be assigned. [cite:1]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Caller name resolution","def":"September 28. Organization contacts fill a missing PSTN name. [cite:1]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Third-party virtual line","def":"September 24. Not ATAs or DECT handsets. [cite:1]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Star during deposit","def":"September 23 blocks the voice portal while a message is recorded. [cite:1]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"AutoCSAT","def":"System controlled. Do not assign the value by hand. [cite:3]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"36 and 13","def":"Export window versus the Analyzer and Search API window named in the same sentence. [cite:3]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Assign To","def":"Webex Connect, Webex Contact Center, or Contact Center Enterprise. [cite:3]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Flow Builder default","def":"Existing routing continues to use Webex Connect Flow Builder by default. [cite:3]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"October 29, 2026","def":"Granular states become general for all customers. Optional until that date. [cite:3] [cite:4]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"W70 firmware","def":"146.87.254.37. Time-issue fix. Announcement 2026-10-07. [cite:6]","room":"T8-R08","href":"rooms/T8-R08-latest-features-radar.html#eco"},{"term":"Webex Calling (in nbedetf)","def":"The multi-tenant cloud call service. Endpoint registration and call routing live in that cloud. [cite:1]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Control Hub","def":"The management portal for the bundled offer, reached at admin.webex.com. re-check [cite:2]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Local gateway","def":"Enterprise or partner edge that provides PSTN and connects a legacy PBX, including Unified CM. [cite:1] re-check [cite:2]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Trunk","def":"The Webex Calling connection to the premises. It terminates on a local gateway or a supported device. [cite:3]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Route group","def":"Trunks grouped for distribution or redundancy. [cite:3]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Cloud PSTN","def":"Cisco Calling Plan or Cloud Connected PSTN for Webex Calling users. [cite:1] [cite:3]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Survivability Gateway","def":"Local IOS-XE gateway that endpoints use when the cloud path is down. Detail is T2-R07. [cite:1]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"PPDIO","def":"Prepare, Plan, Design, Implement, Optimize, as the migration guide uses those phases. [cite:1]","room":"T2-R01","href":"rooms/T2-R01-calling-architecture.html#eco"},{"term":"Losing carrier","def":"The current PSTN provider. The winning carrier is the provider that receives the number. [cite:1]","room":"T6-R06","href":"rooms/T6-R06-number-porting-cutover.html#eco"},{"term":"FOC","def":"Firm order commitment. The losing carrier’s date and time. Requested dates are not confirmed until FOC. [cite:1]","room":"T6-R06","href":"rooms/T6-R06-number-porting-cutover.html#eco"},{"term":"LOA","def":"Letter of agency authorizing Cisco to act for the customer. Some countries use an eLOA filled in Control Hub. [cite:1]","room":"T6-R06","href":"rooms/T6-R06-number-porting-cutover.html#eco"},{"term":"BTN","def":"Billing telephone number. If it ports, a non-ported number is designated as the replacement. [cite:1]","room":"T6-R06","href":"rooms/T6-R06-number-porting-cutover.html#eco"},{"term":"Snapback","def":"Emergency restore of a number to the losing carrier, inside a 1–48 hour window. [cite:1]","room":"T6-R06","href":"rooms/T6-R06-number-porting-cutover.html#eco"},{"term":"PTS","def":"Cisco PSTN Technical Support for Calling Plan number orders, porting, and related questions. [cite:1]","room":"T6-R06","href":"rooms/T6-R06-number-porting-cutover.html#eco"},{"term":"Interop trunk","def":"The certificate-based SIP trunk Cisco creates between Dedicated Instance and multi-tenant Webex Calling over the Webex backbone. [cite:1]","room":"T5-R05","href":"rooms/T5-R05-di-webex-calling-coexistence.html#eco"},{"term":"WXC-DI location","def":"The default multi-tenant location. It needs a PSTN connection and a main number before calls use its route group. [cite:2]","room":"T5-R05","href":"rooms/T5-R05-di-webex-calling-coexistence.html#eco"},{"term":"ECBN","def":"Emergency callback number on that location. When set, an emergency call presents it to the PSTN provider. [cite:1]","room":"T5-R05","href":"rooms/T5-R05-di-webex-calling-coexistence.html#eco"},{"term":"X-DI-WxC-otg","def":"SIP header the normalization script adds toward Webex Calling. [cite:2]","room":"T5-R05","href":"rooms/T5-R05-di-webex-calling-coexistence.html#eco"},{"term":"Group filter","def":"Limits Dedicated Instance Unified CM directory sync to users designated for Dedicated Instance. [cite:3]","room":"T5-R05","href":"rooms/T5-R05-di-webex-calling-coexistence.html#eco"},{"term":"CCP for both","def":"The deployment-model article says both multi-tenant and Dedicated Instance users can use existing Cloud Connect PSTN partner peering to the multi-tenant platform. [cite:3]","room":"T5-R05","href":"rooms/T5-R05-di-webex-calling-coexistence.html#eco"},{"term":"Verify Call Routing","def":"Control Hub simulation of a routing decision. Call source is a cloud user, workspace, virtual line, or premises trunk. [cite:1]","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#eco"},{"term":"CCPP","def":"The troubleshooting article’s name for the cloud connected PSTN provider that relays off-net media. [cite:3]","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#eco"},{"term":"Local Gateway hop","def":"The other off-net path. Media comes through the enterprise, not through the CCP interconnect. [cite:3]","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#eco"},{"term":"+E.164","def":"The format Control Hub saves for CCP DIDs, toll-free numbers, and Local Gateway numbers. [cite:2]","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#eco"},{"term":"Unknown extension length","def":"n0xb944: 2–10 digits for premises-based routing. If you lengthen extensions and the PSTN provider is not E.164, inbound calls can be treated as on-premises local calls. [cite:1]","room":"T7-R07","href":"rooms/T7-R07-sip-trace-reading-lab.html#eco"},{"term":"Data residency","def":"Storage of user data in regional data centers that correspond to the customer’s location. Formerly called data locality. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"GEO","def":"The location set at provisioning for the organization’s users and encryption keys. A later move between GEOs is not supported. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"KMS","def":"The Key Management Service in the organization’s region. It handles requests for keys that encrypt and decrypt spaces, messages, and content in Webex App. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"Country Selector","def":"The Control Hub drop-down during provisioning that maps a country to a data center. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"Data Locations","def":"Account > Info > Data Locations, where an admin verifies Meetings, Messaging, and common application data. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"Country of Operation","def":"The Contact Center setting that confirms that service’s residency. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"Space owner","def":"The organization whose region stores the content that appears in the space. [cite:1]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"iPOP","def":"Internet Point of Presence. The Meetings article lists them separately from data centers. [cite:4]","room":"T1-R07","href":"rooms/T1-R07-data-residency-security.html#eco"},{"term":"Migration Insights","def":"The Control Hub assessment that reads a Unified CM tar. Group CSVs show who should migrate together. [cite:2]","room":"T6-R03","href":"rooms/T6-R03-migration-tools.html#eco"},{"term":"A-FLEX-P-CALL","def":"The entitlement PID the user-migration article says you receive when Webex Calling is the cloud deployment option, used for temporary licensing up to 18 months. [cite:2]","room":"T6-R03","href":"rooms/T6-R03-migration-tools.html#eco"},{"term":"Manifest zip","def":"What Complete migration downloads. It contains a CSV of phone MAC addresses to upload on Unified CM. [cite:2]","room":"T6-R03","href":"rooms/T6-R03-migration-tools.html#eco"},{"term":"UserBasedUCMFeatureMigration","def":"The Python script that processes CDR and writes park and pickup files the feature tool does not currently support. [cite:3]","room":"T6-R03","href":"rooms/T6-R03-migration-tools.html#eco"},{"term":"MPP migration","def":"Enterprise firmware to MPP. 8821 and 8831 are not eligible. 8832NR can migrate with limitations. V15 and later hardware needs at least 11.3.3 MPP and cannot downgrade. [cite:4]","room":"T6-R03","href":"rooms/T6-R03-migration-tools.html#eco"},{"term":"Full administrator","def":"Access to every aspect of how the organization is run. Exclusive of location administrator. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Location administrator","def":"Delegated administration of certain services in assigned locations. Exclusive of other administrator roles. [cite:1] [cite:2]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Advanced troubleshooting access","def":"Live Meeting access. A full administrator cannot assign it to themselves. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Compliance officer","def":"The organization role marked for user-generated content and legal hold. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Services role","def":"A role such as a Webex site role that can be affected when the organizational role changes. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Obsolete CDR role","def":"Webex Calling Detailed Call History API access, marked Obsolete, operational until December 31, 2026. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Partner Hub","def":"The console the role article names for administrators who manage multiple customer organizations. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"Provisioning administrator","def":"In the contact-center table, a partner-organization role that can perform contact-center administrative activities a partner full administrator can perform, and cannot perform user management. [cite:1]","room":"T1-R05","href":"rooms/T1-R05-admin-roles-partner.html#eco"},{"term":"MAC claim","def":"Registration by the device MAC address. The add-device article says every device it lists can use this path. [cite:1]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"Activation code","def":"A 16-digit code from Control Hub. Blank MAC generates one. [cite:1] [cite:2]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"MPP","def":"Multiplatform phone. The activation-code subset is the model list in the core table. [cite:1]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"RoomOS","def":"The article says to use activation codes for RoomOS, and CSV types WEBEX or WEBEX_CALLING for RoomOS workspaces. [cite:1]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"Professional workspace license","def":"Allows up to five of the phone types the April 21, 2026 article names. [cite:3]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"Common area workspace license","def":"Allows one device on the workspace. [cite:3]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"Call on Webex","def":"1:1, non-PSTN calling. The default calling service when you add Board, Desk, or Room devices. [cite:3]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"Companion Mode","def":"The exception that allows one Board and one Room Series device in the same workspace. [cite:3]","room":"T2-R04","href":"rooms/T2-R04-devices-provisioning.html#eco"},{"term":"Directory Connector","def":"The Windows software you download from Control Hub and install on a trusted Windows server. One instance serves one Active Directory domain. [cite:1]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Dry run","def":"A test of the synchronization process. You must do a dry run before a full synchronization. [cite:1]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Full synchronization","def":"The sync that turns directory synchronization on for a new installation, and the sync required for groups. [cite:1]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Incremental synchronization","def":"A sync of changes. The dashboard action is disabled when synchronization is paused or disabled, when a full sync has not completed, or when a sync is in progress. [cite:1]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"uid","def":"The only required cloud attribute in Directory Connector attribute mapping. It must come from an Active Directory attribute in email format. [cite:1]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"SCIM","def":"The REST API that keeps the user list in sync when someone is created, updated, or removed in the Entra application. No on-premises connector. [cite:3]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Bearer token","def":"The secret Entra provisioning uses. The manual retrieval path in the SCIM article says the token is valid for 365 days. [cite:3]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Routing rule","def":"The rule that tells Webex which IdP to use when more than one is configured. Skipping it leaves the IdP inactive. [cite:4]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Hybrid Directory","def":"Named among the Hybrid Services that data residency says are supported in the region, together with Hybrid Calendar, Hybrid Calling, Video Mesh, Hybrid Data Security, and Hybrid Messages. [cite:5]","room":"T1-R02","href":"rooms/T1-R02-identity-directory-sync.html#eco"},{"term":"Callback","def":"A Flow Designer activity that creates a queue task so an agent returns the call. It is not a Calling callback number and not an emergency callback. [cite:2]","room":"T8-R02","href":"rooms/T8-R02-flow-design-patterns.html#eco"},{"term":"Call distribution group","def":"A team-queue expansion step. The contact waits the configured duration, then the next group’s teams are added. [cite:2]","room":"T8-R02","href":"rooms/T8-R02-flow-design-patterns.html#eco"},{"term":"Call Progress Analysis","def":"Detects an answering system or a live voice on a callback. Placement depends on courtesy versus scheduled callback. [cite:2]","room":"T8-R02","href":"rooms/T8-R02-flow-design-patterns.html#eco"},{"term":"Active mode","def":"Endpoints register to the Webex cloud for SIP. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"Survivability mode","def":"Endpoints register to the local Survivability Gateway and use basic backup calling. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"Survivability Gateway","def":"An IOS XE router on the local network that takes registrations when the cloud path is down. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"mode webex-sgw","def":"The configuration mode after which the gateway listens on port 8933. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"max-dn","def":"The directory-number limit on the router. Shared appearances count. Five phones sharing five DNs count as 25. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"FQDN hostname","def":"The certificate name entered in Control Hub. It can be a Subject Alternative Name. DNS population is not mandatory for the secure connection. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"Colocation","def":"Local gateway and survivability gateway services on one Cisco IOS device. re-check [cite:3]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"B-ACD","def":"Basic automatic call distribution on the gateway, with auto-attendant and one call-queue service. Colocation with a local gateway is not supported for this service. [cite:1]","room":"T2-R07","href":"rooms/T2-R07-survivability-gateway.html#eco"},{"term":"CRM connector","def":"The Version 2 package that launches Desktop inside Salesforce, Dynamics 365, or ServiceNow. [cite:1]","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#eco"},{"term":"Lightning","def":"The Salesforce UI these articles support. Classic mode is not supported. [cite:1]","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#eco"},{"term":"CIF","def":"Channel Integration Framework. Version 1 for a single-session Dynamics app. Version 2 for a multi-session app. [cite:2]","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#eco"},{"term":"Channel URL","def":"The Dynamics article’s provider URL on wxcc-crmconnectors.ciscoccservice.com, with a base query for the Dynamics host. [cite:2]","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#eco"},{"term":"webRtcDomain","def":"The Desktop-mode domain for the tenant’s region. Salesforce and ServiceNow list a Singapore value. The Dynamics customize table does not. [cite:1] [cite:2] [cite:3]","room":"T8-R04","href":"rooms/T8-R04-crm-integrations.html#eco"},{"term":"Third-party PBX","def":"A source the Dedicated Instance practice article names. The article does not list vendor objects. [cite:1]","room":"T6-R05","href":"rooms/T6-R05-third-party-pbx-cc.html#eco"},{"term":"DeviceEligibility.csv","def":"A Migration Insights report that identifies devices eligible to move, including third-party devices. [cite:2]","room":"T6-R05","href":"rooms/T6-R05-third-party-pbx-cc.html#eco"},{"term":"Dial number","def":"The free-form agent destination in the voice-channel article. +E.164 is typical. Reachability is required. [cite:3]","room":"T6-R05","href":"rooms/T6-R05-third-party-pbx-cc.html#eco"},{"term":"Direct SIP","def":"The Local Gateway trunk between Webex Calling and a Microsoft Teams tenant for Webex Contact Center agents. [cite:3]","room":"T6-R05","href":"rooms/T6-R05-third-party-pbx-cc.html#eco"},{"term":"JTAPI","def":"The UCCX call-control interface to Unified CM. The integration article says it is sensitive to latency and must be under 60 ms. [cite:4]","room":"T6-R05","href":"rooms/T6-R05-third-party-pbx-cc.html#eco"},{"term":"RACI","def":"Responsible, Accountable, Consulted, Informed, as the Dedicated Instance matrix defines those four letters. [cite:1]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"Service request","def":"The Control Hub object at Calling → Dedicated Instance → Service Request for Day-0 and Day-1 assistance. [cite:3]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"Widespread issue","def":"100 percent of a UC cluster, or an issue across multiple clusters. Cisco troubleshoots non-configuration issues in that band. [cite:1]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"Alerts Center rule","def":"Calling - Maintenance and Outage. The customer or partner configures email, Webex App, or webhooks. [cite:1]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"DRS","def":"Disaster Recovery System on Unified CM, IM and Presence, or Unity Connection. Cisco runs it. Partners do not get access. [cite:2]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"Custom SAN","def":"Not supported on Dedicated Instance certificates. [cite:1]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"n and n-1","def":"The partner operations guide says customers can run the current Collaboration Systems release or the previous one, then states the printed n-1 has entered end of support. Read the live table. [cite:2] re-check","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"Tier 1","def":"Initial technical support included in the Webex Calling subscription at no additional cost for the subscription term. Basic support is 24/7 in English. [cite:4]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"UC application lifecycle request","def":"The service-request type for maintenance schedule questions covering certificate management, software upgrades, or PSIRT fixes. [cite:3]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"DI–MT inter-op request","def":"Changes the location in the selected region on multi-tenant for the default trunks Cisco created. [cite:3]","room":"T5-R04","href":"rooms/T5-R04-di-admin-operations.html#eco"},{"term":"License assignment","def":"An organization or group template that grants selected services to future users, and optionally to existing users when you save. [cite:1]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Active","def":"The state the template article uses for first sign-in, when people can use the associated services. [cite:1]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Preserve licenses","def":"The default when you apply a template to existing users. Clear it to remove licenses the template no longer includes. [cite:1]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Host","def":"A Meetings account type that decreases the meetings license count by one. [cite:1]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Attendee","def":"A Meetings account type that does not decrease the meetings license count. The site must have Attendee account enabled. [cite:1]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Call on Webex","def":"The basic default the article names as 1:1 call, non-PSTN, applied with basic messaging and free Webex Meetings when you have not stated otherwise. [cite:1]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Professional workspace","def":"The Calling workspace license you can upgrade to. The upgrade article says you cannot downgrade it to common area. [cite:3]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Customer Assist","def":"A license the individual-edit article says cannot sit on a user together with Webex Calling standard. [cite:2]","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Work phone number","def":"The directory field Calling auto-assign uses to find a pre-provisioned E.164 number and its location. [cite:4] re-check","room":"T1-R03","href":"rooms/T1-R03-licensing-subscriptions.html#eco"},{"term":"Seven-gate framework","def":"The self-service Dedicated Instance migration sequence in the practice article. [cite:1]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Pre-Migration Assistant","def":"Control Hub discovery and readiness for Unified CM to Dedicated Instance. It does not migrate. [cite:2]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Certified Migration Provider tool","def":"The tool class the assistant article says the partner uses to complete the migration. [cite:2]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Freeze","def":"Data move and validation. Recommended 2–3 weeks. Changes during freeze go on both systems. [cite:1]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Cutover window","def":"In the assistant scheduler, it should not exceed ten hours. Phones in the selected device pools register to Dedicated Instance during that window. [cite:2]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Option 150","def":"The DHCP option the practice article changes so phones learn the Dedicated Instance TFTP. [cite:1]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Rollback","def":"A mirror of the cutover method of procedure, inside the maintenance window. [cite:1]","room":"T5-R06","href":"rooms/T5-R06-di-migration-path.html#eco"},{"term":"Hunt group","def":"A number that rings a defined list of users, workspaces, or virtual lines in a chosen pattern. [cite:1]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"Call queue","def":"A professional-license voice queue that holds calls until an agent is available. [cite:2]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"Auto attendant","def":"A menu that answers and routes to a person, hunt group, or voicemail without a receptionist. [cite:3]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"Call pickup group","def":"An administrator-defined set of users in one location who can answer each other’s ringing lines. [cite:4]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"FAC","def":"Feature access code, also called a star code, dialed on Webex App or an IP phone. [cite:5]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"DNIS","def":"Extra numbers that route to the same call queue while keeping the dialed number’s identity. Up to 100 per queue. [cite:2]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"Skill level","def":"1 is the highest skill on a call queue and 20 is the lowest. [cite:2]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"Wrapping Up","def":"Agents in this state do not receive queued calls unless that default is changed. [cite:2]","room":"T2-R05","href":"rooms/T2-R05-call-features.html#eco"},{"term":"Location","def":"A physical address that organizes users and workspaces, and can hold calling and workspace management together. [cite:1]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Location ID","def":"The identifier Webex generates at create time. Leave it blank in a CSV row that adds a location. Do not edit it. [cite:1]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Floor","def":"A number, and an optional name, on a location. [cite:1]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Disable calling","def":"The action required before a Calling location can be deleted. [cite:1]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"-CALL suffix","def":"The rename applied when a migrated calling location collided with an existing name. [cite:1]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Workspace location versus calling location","def":"Older orgs could have both. A workspace can now be assigned to one location. Double assignment is not supported. [cite:1]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Emergency Service Address","def":"Mandatory for U.S. and Canada Cisco Calling Plan locations in the trunk and dial-plan article. It is set on the location’s PSTN connection. [cite:2]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Routing prefix","def":"A per-location prefix, length 1–7, set under the location’s Calling dialing settings. [cite:3]","room":"T1-R04","href":"rooms/T1-R04-locations-sites.html#eco"},{"term":"Workforce management","def":"An institutional process aimed at productivity, competency, and engagement, typically including forecasting and scheduling. [cite:1]","room":"T9-R01","href":"rooms/T9-R01-wfm-qm-foundations.html#eco"},{"term":"Call centre","def":"An office dealing with a large volume of enquiries by telephone. [cite:2]","room":"T9-R01","href":"rooms/T9-R01-wfm-qm-foundations.html#eco"},{"term":"Basic WFM","def":"The Webex WFO package whose opened article centers on forecasting, scheduling, and agent self-service. [cite:3]","room":"T9-R01","href":"rooms/T9-R01-wfm-qm-foundations.html#eco"},{"term":"Basic QM","def":"The Webex WFO package whose opened article centers on recording and evaluation. [cite:3]","room":"T9-R01","href":"rooms/T9-R01-wfm-qm-foundations.html#eco"},{"term":"MyTime","def":"Web and mobile apps where agents view, manage, and request schedule changes. [cite:3]","room":"T9-R02","href":"rooms/T9-R02-basic-wfm.html#eco"},{"term":"Shift bidding","def":"Agents bid for preferred shifts based on pre-defined rules and fairness settings. [cite:3]","room":"T9-R02","href":"rooms/T9-R02-basic-wfm.html#eco"},{"term":"Intraday management","def":"Dashboards to monitor the day and adapt staffing. [cite:3]","room":"T9-R02","href":"rooms/T9-R02-basic-wfm.html#eco"},{"term":"Real-time adherence","def":"The basic feature list tracks activity against scheduled tasks. The SKU row says the connector is a separate add-on. [cite:3] [cite:4]","room":"T9-R02","href":"rooms/T9-R02-basic-wfm.html#eco"},{"term":"A-FLEX-WFO-NFMB","def":"Named on the Basic WFM and QM SKU row in py6u9h. [cite:4]","room":"T9-R02","href":"rooms/T9-R02-basic-wfm.html#eco"},{"term":"Text search","def":"Filters contacts based on text in a text, email, chat, or SMS body. [cite:3]","room":"T9-R03","href":"rooms/T9-R03-basic-qm.html#eco"},{"term":"Screen recording","def":"Captures agent screen activity alongside audio. [cite:3]","room":"T9-R03","href":"rooms/T9-R03-basic-qm.html#eco"},{"term":"Evaluation form","def":"Built and edited in Basic QM to match quality standards. [cite:3]","room":"T9-R03","href":"rooms/T9-R03-basic-qm.html#eco"},{"term":"Calibration","def":"Listed on the existing QM side of Table 1, not in the Basic column. [cite:3]","room":"T9-R03","href":"rooms/T9-R03-basic-qm.html#eco"},{"term":"A-FLEX-WFO-NQM","def":"The full QM SKU name printed on py6u9h. [cite:4]","room":"T9-R03","href":"rooms/T9-R03-basic-qm.html#eco"},{"term":"A-FLEX-AI-QM","def":"The AI Quality Management add-on SKU printed on 6m6r3fb and nvtdfxk. [cite:5]","room":"T9-R04","href":"rooms/T9-R04-ai-quality-management.html#eco"},{"term":"A-FLEX-AI-QMMB","def":"The AI Quality Management and AI Assistant bundled SKU. [cite:6]","room":"T9-R04","href":"rooms/T9-R04-ai-quality-management.html#eco"},{"term":"Sentiment class","def":"Positive, neutral, or negative for a completed interaction, in the enablement table. [cite:5]","room":"T9-R04","href":"rooms/T9-R04-ai-quality-management.html#eco"},{"term":"Coaching insights","def":"Recommendations from historical interaction data, quality results, and performance metrics. [cite:9]","room":"T9-R04","href":"rooms/T9-R04-ai-quality-management.html#eco"},{"term":"English only","def":"The getting-started FAQ’s current language line. [cite:6]","room":"T9-R04","href":"rooms/T9-R04-ai-quality-management.html#eco"},{"term":"CSR","def":"The interaction-level custom report: customer interactions and their QM metrics. [cite:7]","room":"T9-R05","href":"rooms/T9-R05-qm-analyzer.html#eco"},{"term":"ASR","def":"The agent report: agents by team and operational plus QM metrics. [cite:7]","room":"T9-R05","href":"rooms/T9-R05-qm-analyzer.html#eco"},{"term":"Dead air","def":"Time in the connected portion when neither customer nor agent is speaking. [cite:7]","room":"T9-R05","href":"rooms/T9-R05-qm-analyzer.html#eco"},{"term":"Cross talk","def":"Time the agent spoke over the customer. [cite:7]","room":"T9-R05","href":"rooms/T9-R05-qm-analyzer.html#eco"},{"term":"Neutral band","def":"Sentiment from -45 through +45, inclusive of the between wording on n4jc67x. [cite:7]","room":"T9-R05","href":"rooms/T9-R05-qm-analyzer.html#eco"},{"term":"Cisco AI Assistant","def":"The desktop capability described on nvvv1zb. [cite:10]","room":"T10-R01","href":"rooms/T10-R01-three-ai-names.html#eco"},{"term":"AI Agent Studio","def":"Where scripted and autonomous agents are created before s0qro1 attaches them. [cite:11]","room":"T10-R01","href":"rooms/T10-R01-three-ai-names.html#eco"},{"term":"Virtual Agent V2","def":"The Flow Designer activity for speech-based AI conversations. [cite:11]","room":"T10-R01","href":"rooms/T10-R01-three-ai-names.html#eco"},{"term":"Virtual Agent–Voice","def":"The IVR integration with third-party cloud AI on n6gaghu. [cite:13]","room":"T10-R01","href":"rooms/T10-R01-three-ai-names.html#eco"},{"term":"Handled","def":"Virtual agent execution completed. [cite:11]","room":"T10-R02","href":"rooms/T10-R02-virtual-agent-v2.html#eco"},{"term":"Escalated","def":"The call must go to a human agent. [cite:11]","room":"T10-R02","href":"rooms/T10-R02-virtual-agent-v2.html#eco"},{"term":"Errored","def":"Any error between the virtual agent and the caller. [cite:11]","room":"T10-R02","href":"rooms/T10-R02-virtual-agent-v2.html#eco"},{"term":"TranscriptURL","def":"Output variable pointing at the transcript. [cite:11]","room":"T10-R02","href":"rooms/T10-R02-virtual-agent-v2.html#eco"},{"term":"MetaData","def":"JSON received from the agent for fulfillment, a custom event, or a transfer. [cite:11]","room":"T10-R02","href":"rooms/T10-R02-virtual-agent-v2.html#eco"},{"term":"Global_Language","def":"Flow variable that overrides the Studio input language. Example on the page: fr-CA. [cite:11]","room":"T10-R03","href":"rooms/T10-R03-language-voice-events.html#eco"},{"term":"Global_VoiceName","def":"Flow variable that overrides the output voice. Example: en-US-Jennifer. [cite:11]","room":"T10-R03","href":"rooms/T10-R03-language-voice-events.html#eco"},{"term":"State event","def":"Event Name plus Event Data sent to the agent’s handler. [cite:11]","room":"T10-R03","href":"rooms/T10-R03-language-voice-events.html#eco"},{"term":"Voice-only custom events","def":"The article’s current line for scripted and autonomous agents. [cite:11]","room":"T10-R03","href":"rooms/T10-R03-language-voice-events.html#eco"},{"term":"Six channels","def":"WhatsApp, SMS, Email, Facebook Messenger, Apple Messages for Business, Live Chat. [cite:11]","room":"T10-R04","href":"rooms/T10-R04-digital-ai-channels.html#eco"},{"term":"Process Message","def":"Sends the customer message and returns the agent response. [cite:11]","room":"T10-R04","href":"rooms/T10-R04-digital-ai-channels.html#eco"},{"term":"Close session","def":"Closes the AI agent session. Inactive sessions can close automatically. [cite:11]","room":"T10-R04","href":"rooms/T10-R04-digital-ai-channels.html#eco"},{"term":"onAgentHandover","def":"The agent raised a request to hand over to human agents. [cite:11]","room":"T10-R04","href":"rooms/T10-R04-digital-ai-channels.html#eco"},{"term":"onTimeOut","def":"The agent has not responded in not more than 15 seconds. [cite:11]","room":"T10-R04","href":"rooms/T10-R04-digital-ai-channels.html#eco"},{"term":"Specific customers","def":"The availability line for autonomous voice. [cite:11]","room":"T10-R05","href":"rooms/T10-R05-voice-ai-limits.html#eco"},{"term":"English only","def":"AI Quality Management FAQ, not the Studio language matrix. [cite:6]","room":"T10-R05","href":"rooms/T10-R05-voice-ai-limits.html#eco"},{"term":"Confirm","def":"A sources row with no URL, used when a page was not opened.","room":"T10-R05","href":"rooms/T10-R05-voice-ai-limits.html#eco"},{"term":"Sibling lab","def":"A CypherMonkey Labs study site that opened in 2026-10. [cite:21]","room":"T10-R05","href":"rooms/T10-R05-voice-ai-limits.html#eco"},{"term":"Webex Calling, in nbedetf","def":"Multi-tenant only. The guide says the term always means that. [cite:14]","room":"T11-R01","href":"rooms/T11-R01-bridge-is-not-a-cutover.html#eco"},{"term":"Local Gateway","def":"A bridge for PSTN and for calls between Unified CM registered and cloud registered endpoints. [cite:14]","room":"T11-R01","href":"rooms/T11-R01-bridge-is-not-a-cutover.html#eco"},{"term":"PPDIO","def":"Prepare, Plan, Design, Implement, Optimize. [cite:14]","room":"T11-R01","href":"rooms/T11-R01-bridge-is-not-a-cutover.html#eco"},{"term":"Stay case","def":"A listed reason to keep on-premises call control, including a contact center that is not moving. [cite:14]","room":"T11-R01","href":"rooms/T11-R01-bridge-is-not-a-cutover.html#eco"},{"term":"Phased migration","def":"The reason the guide allows an on-premises Local Gateway while both systems exist. [cite:14]","room":"T11-R02","href":"rooms/T11-R02-local-gateway-bridge.html#eco"},{"term":"Certified third-party SBC","def":"Allowed as a Local Gateway, beside the named Cisco routers. [cite:14]","room":"T11-R02","href":"rooms/T11-R02-local-gateway-bridge.html#eco"},{"term":"Cloud PSTN","def":"Cisco Calling Plan or Cloud Connect, no on-premises gear. [cite:14]","room":"T11-R02","href":"rooms/T11-R02-local-gateway-bridge.html#eco"},{"term":"Trunking model","def":"A section on the Local Gateway getting-started page. Details stay in that article. [cite:19]","room":"T11-R02","href":"rooms/T11-R02-local-gateway-bridge.html#eco"},{"term":"60 ms RTT","def":"The UCCX to Unified CM JTAPI limit printed on nmhk7ve. [cite:15]","room":"T11-R03","href":"rooms/T11-R03-di-contact-center.html#eco"},{"term":"Home Agent variation","def":"DI phones, on-premises UCCX, Extend and Connect. No silent monitoring. [cite:15]","room":"T11-R03","href":"rooms/T11-R03-di-contact-center.html#eco"},{"term":"Certificate trunk","def":"Required for Dedicated Instance to Webex Calling Contact Center. Registration-based trunks are no longer supported. [cite:15]","room":"T11-R03","href":"rooms/T11-R03-di-contact-center.html#eco"},{"term":"Inter-op SIP trunk","def":"The default trunk the article says Cisco creates between the calling platforms. [cite:15]","room":"T11-R03","href":"rooms/T11-R03-di-contact-center.html#eco"},{"term":"HCS Contact Center","def":"Named as not covered. [cite:15]","room":"T11-R03","href":"rooms/T11-R03-di-contact-center.html#eco"},{"term":"Discovery tool","def":"The UCCX extraction jar described on 0hd75db. [cite:16]","room":"T11-R04","href":"rooms/T11-R04-uccx-to-wxcc.html#eco"},{"term":"5000 rows","def":"The bulk-operations limit for one import CSV. Split the file if it is larger. [cite:16]","room":"T11-R04","href":"rooms/T11-R04-uccx-to-wxcc.html#eco"},{"term":"Skip prompts","def":"application-pro.yml can set skipPrompts. The default extracts prompts. [cite:16]","room":"T11-R04","href":"rooms/T11-R04-uccx-to-wxcc.html#eco"},{"term":"Tenant data tool","def":"n2puc5z. Enterprise admin-portal data between tenants. Not the UCCX jar. [cite:17]","room":"T11-R04","href":"rooms/T11-R04-uccx-to-wxcc.html#eco"},{"term":"Documented calling bridge","def":"Unified CM to Webex Calling multi-tenant, with Local Gateway. [cite:14]","room":"T11-R05","href":"rooms/T11-R05-other-platforms.html#eco"},{"term":"Documented CCX bridge","def":"Discovery tool and bulk operations into Webex Contact Center. [cite:16]","room":"T11-R05","href":"rooms/T11-R05-other-platforms.html#eco"},{"term":"Not a bridge","def":"n2puc5z, tenant to tenant inside Webex CCE admin data. [cite:17]","room":"T11-R05","href":"rooms/T11-R05-other-platforms.html#eco"},{"term":"Sibling lab","def":"A cyphermonkeylabs.com classroom that returned HTTP 200 in this pass. [cite:21]","room":"T11-R05","href":"rooms/T11-R05-other-platforms.html#eco"}]};
